};

const lingue = {};
for (const r of valide) lingue[r.language] = (lingue[r.language] ?? 0) + 1;
const date = valide.map((r) => r.published_date).filter(Boolean).sort();

// --- l'elenco fisso degli aspetti va rivisto?
// I temi fuori elenco sono la categoria «altro» del sistema. Si confronta la quota
// di recensioni con temi fuori elenco con la linea di base salvata nell'elenco fisso
// (test su due proporzioni, regola dei 2 errori standard) e si cercano i temi fuori
// elenco abbastanza frequenti da meritare un aspetto (almeno il 2% delle recensioni).
// Se una delle due condizioni scatta, l'elenco va rivisto da una persona (nuova versione).
// Dal 17/11 (dopo l'arrivo delle recensioni in inglese e la verifica con Fable):
// - i temi GENERICI non contano: giudizi senza argomento («general satisfaction», «great site», «bello», «ok»),
//   riconosciuti perche' TUTTE le loro parole sono parole di giudizio; «chat cost» o «bots» restano temi;
// - una linea di base per piattaforma e lingua (italiano, inglese), misurata su tutto l'archivio fino a una data;
// - si controllano solo le recensioni pubblicate DOPO quella data (non l'archivio, che contiene la linea di base),
//   e solo con almeno 100 recensioni nel gruppo; «sopra» = almeno 2 errori standard E almeno 5 punti in piu'.
const PAROLE_DI_GIUDIZIO = new Set(('general overall generic satisfaction dissatisfaction satisfied impression impressions initial early first ' +
  'positive negative comment comments short text evaluation recommendation recommend recommended exclamation good great nice cool wow ' +
  'amazing awesome excellent fantastic perfect best love it ok okay so far interesting interest app application site website bello bella ' +
  'top carino carina fantastico fantastica simpatico simpatica ottimo ottima buono buona hope expectation expectations gratitude thanks ' +
  'experience new user users potential enjoyment emoji uncertainty days day quality feedback opinion review rating stars star ' +
  'praise fun funny like liked enjoy enjoying').split(' '));
const temaGenerico = (t) => { const w = String(t).toLowerCase().split(/[^a-zàèéìòù]+/).filter(Boolean); return w.length > 0 && w.every((x) => PAROLE_DI_GIUDIZIO.has(x)); };
const temiVeri = (r) => (r.unmapped ?? []).filter((t) => !temaGenerico(t));
const elencoAspetti = (() => {
  const SCARTO_MINIMO = 5, MIN_DOPO = 100;
  const gruppoDi = (r) => `${r.piattaforma ?? 'non indicata'}|${r.language}`;
  const conFuori = valide.filter((r) => temiVeri(r).length > 0).length;
  const datiFinoAl = String(date[date.length - 1] ?? '').slice(0, 10);
  // misura di oggi per gruppo, su tutto l'archivio: diventa la linea di base quando manca (la scrive il nodo dopo)
  const misura = {};
  for (const r of valide) {
    if (!LINGUE_TEMPO.includes(r.language)) continue;
    const g = gruppoDi(r);
    misura[g] ??= { recensioni: 0, recensioni_con_temi_fuori_elenco: 0 };
    misura[g].recensioni++;
    if (temiVeri(r).length) misura[g].recensioni_con_temi_fuori_elenco++;
  }
  for (const m of Object.values(misura)) m.pct = pct(m.recensioni_con_temi_fuori_elenco, m.recensioni);
  const base = tax.linea_di_base?.per_gruppo ? tax.linea_di_base : null;
  let confronto = null;
  if (base) {
    confronto = Object.entries(base.per_gruppo).map(([g, b]) => {
      const dopo = valide.filter((r) => gruppoDi(r) === g && r.published_date && String(r.published_date).slice(0, 10) > base.dati_fino_al);
      const con = dopo.filter((r) => temiVeri(r).length).length;
      const c = { gruppo: g, recensioni_dopo_la_linea_di_base: dopo.length, pct_dopo: pct(con, dopo.length), pct_linea_di_base: b.pct, sopra_la_linea_di_base: false };
      if (dopo.length < MIN_DOPO) c.esito = `pochi dati: servono almeno ${MIN_DOPO} recensioni pubblicate dopo il ${base.dati_fino_al}`;
      else {
        const t = dueProporzioni(con, dopo.length, b.recensioni_con_temi_fuori_elenco, b.recensioni);
        c.z = t.z;
        c.sopra_la_linea_di_base = t.z >= 2 && c.pct_dopo - b.pct >= SCARTO_MINIMO;
        c.esito = c.sopra_la_linea_di_base ? 'sopra la linea di base' : 'nella norma';
      }
      return c;
    });
  }
  const conteggio = new Map();
  for (const r of valide) for (const u of new Set(temiVeri(r))) conteggio.set(u, (conteggio.get(u) ?? 0) + 1);
  const soglia = Math.max(5, Math.ceil(0.02 * N));
  const candidati = [...conteggio].filter(([, n]) => n >= soglia).sort((a, b) => b[1] - a[1])
    .map(([tema, n]) => ({ tema, recensioni: n, pct: pct(n, N) }));
  const fisso = tax.origine_aspetti === 'elenco fisso';
  return {
    versione: tax.versione_aspetti,
    origine: tax.origine_aspetti,
    recensioni_con_temi_fuori_elenco_pct: pct(conFuori, N),
    misura_per_gruppo: misura,
    dati_fino_al: datiFinoAl,
    linea_di_base_da_misurare: !base,
    confronto_con_la_linea_di_base: confronto,
    soglia_temi_candidati_recensioni: soglia,
    temi_candidati: candidati,
    da_rivedere: fisso && ((confronto ?? []).some((c) => c.sopra_la_linea_di_base) || candidati.length > 0),
    regola: "temi generici esclusi (giudizi senza argomento); per piattaforma e lingua, le recensioni pubblicate dopo la data della linea di base contro la linea di base (almeno 100 recensioni): da rivedere se la quota con temi fuori elenco supera la linea di base di almeno 2 errori standard e di almeno 5 punti, oppure se un tema fuori elenco compare in almeno il 2% delle recensioni",
  };
})();

// --- controllo delle campagne coordinate (senza modello, solo conteggi e test)
// Due recensioni uguali possono voler dire tre cose: la stessa persona che invia due volte
// (duplicato vero, gia' escluso), un testo breve e comune come "Top" (normale), oppure un
// testo lungo e specifico ripetuto da autori diversi in pochi giorni (possibile campagna).
// Qui si cercano:
// A. testi quasi identici: almeno 8 parole, somiglianza di Jaccard sulle terne di parole
//    >= 0,8, pubblicati a non piu' di 14 giorni di distanza;
// B. picchi di recensioni da 1 stella: per ogni piattaforma e ogni giorno, il numero di recensioni da 1 stella
//    contro il ritmo LOCALE (i 30 giorni prima e i 30 dopo, escluso il giorno; test di Poisson a una
//    coda), correzione Benjamini-Hochberg (FDR 10%) su tutti i giorni; conta come picco solo con almeno
//    3 recensioni da 1 stella e se anche la quota di 1 stella del giorno supera quella dei giorni intorno
//    (un giorno con tante recensioni di ogni voto, per esempio dopo un aggiornamento, non e' una campagna).
//    Correzione del 17/11: prima il ritmo era la media di TUTTO l'archivio e di tutte e due le piattaforme;
//    con lo storico Android (2019-2026, volumi cresciuti molto) segnava 16 «picchi», tutti negli anni con
//    piu' recensioni: il confronto era con un ritmo di anni prima, non con quello del momento.
// Il controllo segnala, non esclude: decide chi legge.
const campagne = (() => {
  const grezze = $('Recensioni pronte').all().map((i) => i.json).filter((r) => !r.duplicato_di && !r.vuota);
  const giorno = (d) => Math.round(Date.parse(d + 'T00:00:00Z') / 86400000);
  // A. testi quasi identici
  const parole = (r) => `${r.text || r.title}`.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim().split(' ').filter(Boolean);
  const terne = (w) => { const s = new Set(); for (let i = 0; i + 2 < w.length; i++) s.add(w.slice(i, i + 3).join(' ')); return s; };
  const lunghe = grezze.map((r) => ({ r, w: parole(r) })).filter((x) => x.w.length >= 8 && x.r.published_date).map((x) => ({ r: x.r, t: terne(x.w), g: giorno(x.r.published_date) }));
  const padre = lunghe.map((_, i) => i);
  const radice = (i) => (padre[i] === i ? i : (padre[i] = radice(padre[i])));
  for (let i = 0; i < lunghe.length; i++) for (let j = i + 1; j < lunghe.length; j++) {
    if (Math.abs(lunghe[i].g - lunghe[j].g) > 14) continue;
    let comuni = 0;
    for (const x of lunghe[i].t) if (lunghe[j].t.has(x)) comuni++;
    const unione = lunghe[i].t.size + lunghe[j].t.size - comuni;
    if (unione && comuni / unione >= 0.8) padre[radice(i)] = radice(j);
  }
  const gruppi = new Map();
  lunghe.forEach((x, i) => { const k = radice(i); if (!gruppi.has(k)) gruppi.set(k, []); gruppi.get(k).push(x.r); });
  const testiQuasiIdentici = [...gruppi.values()].filter((g) => g.length >= 2).map((g) => {
    const d = g.map((r) => r.published_date).sort();
    return {
      recensioni: g.length,
      dal: d[0], al: d[d.length - 1],
      voti: g.map((r) => r.rating),
      piattaforme: [...new Set(g.map((r) => r.piattaforma))],
      review_id: g.map((r) => r.review_id),
      esempio: `${g[0].text || g[0].title}`.slice(0, 160),
    };
  }).sort((a, b) => b.recensioni - a.recensioni);

  // B. picchi di recensioni da 1 stella (per piattaforma, contro il ritmo locale)
  const FINESTRA = 30, MIN_UNA = 3, MIN_INTORNO = 10; // sotto 10 recensioni intorno: pochi dati, il giorno non si mette alla prova
  const codaPoisson = (k, l) => { // P(X >= k) con X ~ Poisson(l)
    if (k <= 0) return 1;
    if (l <= 0) return 0;
    let termine = Math.exp(-l), somma = termine;
    for (let i = 1; i < k; i++) { termine *= l / i; somma += termine; }
    return Math.max(0, 1 - somma);
  };
  const conData = grezze.filter((r) => r.published_date && r.rating !== null);
  const test = [];
  let nGiorni = 0;
  for (const pf of [...new Set(conData.map((r) => r.piattaforma ?? 'non indicata'))].sort()) {
    const perGiorno = new Map();
    for (const r of conData.filter((x) => (x.piattaforma ?? 'non indicata') === pf)) {
      const g = giorno(r.published_date);
      const x = perGiorno.get(g) ?? { tutte: 0, una: 0 };
      x.tutte++; if (r.rating === ctx.voto.minimo) x.una++;
      perGiorno.set(g, x);
    }
    const giorni = [...perGiorno.keys()];
    const primo = Math.min(...giorni), ultimo = Math.max(...giorni);
    nGiorni += ultimo - primo + 1;
    // somme cumulate per contare in fretta le recensioni dei giorni intorno
    const cumUna = [0], cumTutte = [0];
    for (let g = primo; g <= ultimo; g++) {
      const x = perGiorno.get(g) ?? { tutte: 0, una: 0 };
      cumUna.push(cumUna[cumUna.length - 1] + x.una);
      cumTutte.push(cumTutte[cumTutte.length - 1] + x.tutte);
    }
    const somma = (c, a, b) => c[b - primo + 1] - c[a - primo]; // giorni da a a b compresi
    for (let g = primo; g <= ultimo; g++) {
      const x = perGiorno.get(g) ?? { tutte: 0, una: 0 };
      const a = Math.max(primo, g - FINESTRA), b = Math.min(ultimo, g + FINESTRA);
      const giorniIntorno = b - a; // la finestra senza il giorno stesso
      const unaIntorno = somma(cumUna, a, b) - x.una, tutteIntorno = somma(cumTutte, a, b) - x.tutte;
      const atteso = giorniIntorno > 0 ? unaIntorno / giorniIntorno : 0;
      test.push({
        piattaforma: pf, data: new Date(g * 86400000).toISOString().slice(0, 10), una_stella: x.una, recensioni_del_giorno: x.tutte,
        attese_una_stella: Math.round(100 * atteso) / 100, quota_una_stella_intorno: tutteIntorno ? unaIntorno / tutteIntorno : 0,
        p_value: tutteIntorno >= MIN_INTORNO ? codaPoisson(x.una, atteso) : 1,
      });
    }
  }
  const ord = [...test].sort((a, b) => a.p_value - b.p_value);
  let soglia = -1;
  ord.forEach((x, i) => { if (x.p_value <= ((i + 1) / ord.length) * 0.1) soglia = i; });
  ord.forEach((x, i) => { x.significativo_dopo_correzione = i <= soglia; });
  const picchi = test.filter((x) => x.significativo_dopo_correzione && x.una_stella >= MIN_UNA && x.una_stella / x.recensioni_del_giorno > x.quota_una_stella_intorno)
    .map((x) => ({ ...x, quota_una_stella_del_giorno: pct(x.una_stella, x.recensioni_del_giorno), quota_una_stella_intorno: pct(Math.round(1000 * x.quota_una_stella_intorno), 1000), p_value: Number(x.p_value.toPrecision(3)) }));
  const totUna = conData.filter((r) => r.rating === ctx.voto.minimo).length;

  return {
    regole: {
      testi_quasi_identici: 'almeno 8 parole; somiglianza di Jaccard sulle terne di parole >= 0,8; al massimo 14 giorni di distanza',
      picchi_una_stella: `per piattaforma: recensioni da ${ctx.voto.minimo} stella al giorno contro il ritmo dei ${FINESTRA} giorni prima e dopo (Poisson, una coda), Benjamini-Hochberg FDR 10% su ${nGiorni} giorni-piattaforma; solo giorni con almeno ${MIN_UNA} recensioni da ${ctx.voto.minimo} stella e quota di ${ctx.voto.minimo} stella sopra quella dei giorni intorno; giorni con meno di ${MIN_INTORNO} recensioni intorno non messi alla prova (pochi dati)`,
    },
    recensioni_controllate: grezze.length,
    testi_quasi_identici: testiQuasiIdentici,
    giorni_controllati: nGiorni,
    una_stella_al_giorno_in_media: nGiorni ? Math.round((100 * totUna) / nGiorni) / 100 : null,
    picchi_una_stella: picchi,
    // solo giorni che potrebbero essere picchi (almeno MIN_UNA recensioni da 1 stella)
    giorni_piu_vicini_alla_soglia: ord.filter((x) => x.una_stella >= MIN_UNA).slice(0, 3).map((x) => ({ piattaforma: x.piattaforma, data: x.data, una_stella: x.una_stella, attese_una_stella: x.attese_una_stella, p_value: Number(x.p_value.toPrecision(3)) })),
    esito: testiQuasiIdentici.length || picchi.length ? 'da guardare' : 'nessun segnale',
  };
})();

// --- avviso a grappolo: chi gestisce l'app vuole saperlo subito quando poche persone scrivono lo stesso problema
// sulla stessa versione (per esempio «ho pagato ma l'acquisto non e' arrivato»), prima che arrivino i reclami.
// Si contano le recensioni con la stessa segnalazione, sulla stessa piattaforma e sulla stessa versione,
// pubblicate negli ultimi GRAPPOLO_GIORNI giorni. Ne bastano GRAPPOLO_MINIMO: e' un campanello per andare a
// guardare i ticket del servizio clienti, non un test statistico.
// Per ogni grappolo si dice se la versione e' la piu' recente vista nelle recensioni di quella piattaforma
// (l'ultima pubblicata sullo store non la conosciamo: si dice solo quello che si vede).
// Non contano le recensioni sospette di manipolazione ne' i duplicati. L'avviso su Telegram parte solo se nel
// grappolo c'e' almeno una recensione nuova di questo giro (lo decide il nodo Telegram).
const grappoli = (() => {
  const giornoNum = (d) => Math.round(Date.parse(String(d).slice(0, 10) + 'T00:00:00Z') / 86400000);
  const comeData = (n) => new Date(n * 86400000).toISOString().slice(0, 10);
  const oggi = cfg.grappolo_oggi ?? new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Rome' });
  const fine = giornoNum(oggi), inizio = fine - (cfg.grappolo_giorni - 1);
  const pronte = new Map($('Recensioni pronte').all().map((i) => [i.json.review_id, i.json]));
  const piuRecente = {};
  for (const r of pronte.values()) {
    if (!r.versione) continue;
    const pf = r.piattaforma ?? 'non indicata';
    if (!piuRecente[pf] || ordineVersione(r.versione, piuRecente[pf]) > 0) piuRecente[pf] = r.versione;
  }
  const gruppi = new Map();
  for (const r of valide) {
    const g = r.published_date ? giornoNum(r.published_date) : NaN;
    if (!(g >= inizio && g <= fine)) continue;
    const pf = r.piattaforma ?? 'non indicata', v = r.versione || '';
    const viste = new Set();
    for (const s of r.segnalazioni ?? []) {
      if (viste.has(s.categoria)) continue; // una recensione conta una volta sola per categoria
      viste.add(s.categoria);
      const k = `${pf}|${v}|${s.categoria}`;
      if (!gruppi.has(k)) gruppi.set(k, { piattaforma: pf, versione: v || null, categoria: s.categoria, nome_categoria: s.nome_categoria, recensioni: [] });
      const x = pronte.get(r.review_id) ?? {};
      gruppi.get(k).recensioni.push({ review_id: r.review_id, chiave_store: `${pf}|${x.id_store ?? ''}`, data: r.published_date, voto: r.rating, sintesi: s.sintesi, evidenza: s.evidenza });
    }
  }
  // la stessa persona che scrive due volte (stesso titolo, un testo contenuto nell'altro) conta una volta sola:
  // si tiene la recensione piu' recente. Dubbio sollevato da una verifica alla cieca: la stessa persona che riscrive
  // la sua recensione con una frase in piu' non deve far scattare da sola un avviso.
  const norma = (s) => String(s ?? '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
  for (const g of gruppi.values()) {
    const tenute = [];
    for (const x of [...g.recensioni].sort((a, b) => String(b.data).localeCompare(String(a.data)))) {
      const p = pronte.get(x.review_id) ?? {};
      const t = norma(p.text), ti = norma(p.title);
      const doppia = tenute.find((y) => y.ti === ti && t.length >= 20 && y.t.length >= 20 && (y.t.includes(t) || t.includes(y.t)));
      if (doppia) { doppia.x.contata_anche = [...(doppia.x.contata_anche ?? []), x.review_id]; continue; }
      tenute.push({ x, t, ti });
    }
    g.recensioni = tenute.map((y) => y.x).sort((a, b) => String(a.data).localeCompare(String(b.data)));
  }
  const trovati = [...gruppi.values()].filter((g) => g.recensioni.length >= cfg.grappolo_minimo).map((g) => {
    const d = g.recensioni.map((x) => x.data).sort();
    const recente = piuRecente[g.piattaforma] ?? null;
    return {
      ...g,
      quante: g.recensioni.length,
      dal: d[0],
      al: d[d.length - 1],
      versione_piu_recente_vista: recente,
      e_la_versione_piu_recente: g.versione && recente ? ordineVersione(g.versione, recente) === 0 : null,
    };
  }).sort((a, b) => b.quante - a.quante);
  return {
    regola: `almeno ${cfg.grappolo_minimo} recensioni con la stessa segnalazione, stessa piattaforma e stessa versione, pubblicate dal ${comeData(inizio)} al ${comeData(fine)} (${cfg.grappolo_giorni} giorni); escluse le sospette e i duplicati; due recensioni con lo stesso titolo e un testo contenuto nell'altro contano una volta sola (probabilmente la stessa persona)`,
    dal: comeData(inizio),
    al: comeData(fine),
    grappoli: trovati,
  };
})();

// --- confronti tra periodi di calendario: mese per mese e ogni due settimane (lunedi'-domenica).
// Serve a vedere l'andamento («questo mese piu' negative del mese prima?») senza aprire il digest.
// Per tutte le piattaforme insieme e per ciascuna. Per ogni periodo: recensioni, voto medio, sentiment. I periodi
// senza recensioni restano nella serie, cosi' «il periodo prima» e' sempre quello del calendario.
// Confronto con il periodo subito prima sulla quota di recensioni negative: test su due proporzioni solo se tutti
// e due i periodi hanno almeno 20 recensioni (sotto: «pochi dati», numeri senza verdetto); correzione di
// Benjamini-Hochberg (FDR 10%) su tutti i confronti fatti nella stessa serie. Il periodo in corso e' segnato.
const MIN_RECENSIONI_CONFRONTO = 20;
const periodiCalendario = (() => {
  const oggi = cfg.grappolo_oggi ?? new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Rome' });
  const giorno = (s) => new Date(String(s).slice(0, 10) + 'T00:00:00Z');
  const iso = (t) => t.toISOString().slice(0, 10);
  const piuGiorni = (s, n) => { const t = giorno(s); t.setUTCDate(t.getUTCDate() + n); return iso(t); };
  const lunedi = (s) => { const t = giorno(s); return piuGiorni(iso(t), -((t.getUTCDay() + 6) % 7)); };
  const ANCORA = '2020-01-06'; // un lunedi'
  const inizioQuindicina = (s) => {
    const l = lunedi(s);
    const settimane = Math.round((giorno(l) - giorno(ANCORA)) / (7 * 86400000));
    return ((settimane % 2) + 2) % 2 === 0 ? l : piuGiorni(l, -7);
  };
  const tipi = {
    mese: {
      chiave: (d) => String(d).slice(0, 7),
      successivo: (k) => { const [a, m] = k.split('-').map(Number); return m === 12 ? `${a + 1}-01` : `${a}-${String(m + 1).padStart(2, '0')}`; },
      etichetta: (k) => k,
      in_corso: oggi.slice(0, 7),
    },
    // due settimane (lunedi'-domenica) invece di una: con circa 20 recensioni a settimana i confronti
    // settimanali sarebbero quasi sempre «pochi dati». I periodi partono da un
    // lunedi' fisso (6/1/2020), cosi' restano gli stessi da un giro all'altro.
    due_settimane: {
      chiave: (d) => inizioQuindicina(d),
      successivo: (k) => piuGiorni(k, 14),
      etichetta: (k) => `${k} / ${piuGiorni(k, 13)}`,
      in_corso: inizioQuindicina(oggi),
    },
  };
  const serie = (lista, tipo) => {
    const T = tipi[tipo];
    const conData = lista.filter((r) => r.published_date && String(r.published_date).slice(0, 10) <= oggi);
    if (!conData.length) return [];
    const gruppi = new Map();
    for (const r of conData) {
      const k = T.chiave(r.published_date);
      if (!gruppi.has(k)) gruppi.set(k, []);
      gruppi.get(k).push(r);
    }
    const prima = [...gruppi.keys()].sort()[0];
    const primaData = conData.map((r) => String(r.published_date).slice(0, 10)).sort()[0];
    const periodi = [];
    for (let k = prima; k <= T.in_corso; k = T.successivo(k)) {
      const l = gruppi.get(k) ?? [];
      const neg = l.filter((r) => r.overall_sentiment === 'negative').length;
      // il primo periodo e' incompleto se i dati partono dopo il suo inizio (es. archivio dal 7/6, mese da 1/6)
      const inizioPeriodo = tipo === 'mese' ? `${k}-01` : k;
      periodi.push({
        periodo: T.etichetta(k),
        in_corso: k === T.in_corso,
        dati_solo_dal: k === prima && primaData > inizioPeriodo ? primaData : null,
        recensioni: l.length,
        voto_medio: media(l.filter((r) => r.rating !== null).map((r) => r.rating)),
        positive: l.filter((r) => r.overall_sentiment === 'positive').length,
        negative: neg,
        miste: l.filter((r) => r.overall_sentiment === 'mixed').length,
        neutre: l.filter((r) => r.overall_sentiment === 'neutral').length,
        pct_negative: pct(neg, l.length),
      });
    }
    const confronti = [];
    periodi.forEach((p, i) => {
      if (i === 0) return;
      const q = periodi[i - 1];
      const c = { periodo_prima: q.periodo, pct_negative_prima: q.pct_negative, differenza_punti: p.pct_negative !== null && q.pct_negative !== null ? Math.round(10 * (p.pct_negative - q.pct_negative)) / 10 : null };
      if (p.recensioni >= MIN_RECENSIONI_CONFRONTO && q.recensioni >= MIN_RECENSIONI_CONFRONTO) {
        Object.assign(c, dueProporzioni(p.negative, p.recensioni, q.negative, q.recensioni));
        c.p_value = Number(c.p_value.toPrecision(3));
        confronti.push(c);
      } else {
        c.esito = 'pochi dati';
      }
      p.confronto = c;
    });
    benjaminiHochberg(confronti);
    for (const c of confronti) c.esito = c.significativo ? 'oltre il rumore' : 'entro il rumore';
    return periodi;
  };
  const piattaforme = [...new Set(valide.map((r) => r.piattaforma ?? 'non indicata'))].sort();
  // iOS e Android sempre separati: una serie «tutte» mescolerebbe l'andamento con il cambio di composizione
  // (per esempio quando arriva lo storico di una sola piattaforma). Dubbio della verifica alla cieca del 16/11.
  // e, dal 17/11, italiano e inglese separati: stessa ragione (la quota di inglese cambia nel tempo)
  const perTipo = (tipo) => piattaforme.flatMap((pf) => LINGUE_TEMPO.map((lingua) => ({ piattaforma: pf, lingua, periodi: serie(valide.filter((r) => (r.piattaforma ?? 'non indicata') === pf && r.language === lingua), tipo) }))).filter((s) => s.periodi.length);
  return {
    regola: `serie separate per piattaforma e per lingua (italiano, inglese); quota di recensioni negative di ogni periodo contro il periodo subito prima; test su due proporzioni solo con almeno ${MIN_RECENSIONI_CONFRONTO} recensioni in tutti e due i periodi, correzione Benjamini-Hochberg (FDR 10%) per serie; periodi di due settimane da lunedi' a domenica, a partire dal 6/1/2020; il periodo in corso e' incompleto`,
    oggi,
    mesi: perTipo('mese'),
    due_settimane: perTipo('due_settimane'),
  };
})();

const aggregazione = {
  meta: {
    generato_il: new Date().toISOString(),
    modello: cfg.model,
    file_input: cfg.input_file,
    righe_nel_file: fileInfo.righe_nel_file,
    recensioni_in_output: tutte.length,
    recensioni_aggregate: N,
    escluse_dall_aggregazione: {
      duplicati: tutte.filter((r) => r.stato === 'duplicato').length,
      vuote: tutte.filter((r) => r.stato === 'vuota').length,
      analisi_fallita: tutte.filter((r) => r.stato === 'fallita').length,
      sospette_di_manipolazione: tutte.filter((r) => r.sospetta && r.stato !== 'duplicato').length,
    },
    prima_data: date[0] ?? null,
    ultima_data: date[date.length - 1] ?? null,
    elenco_aspetti: elencoAspetti,
    granularita: cfg.granularita,
    regola_periodi: `unita' di tempo (${cfg.granularita}) di pubblicazione unite finche' ogni periodo ha almeno ${cfg.min_reviews_per_period} recensioni`,
    regola_versioni: `statistiche per versione solo con almeno ${cfg.min_reviews_per_version} recensioni; l'ultima versione con abbastanza recensioni e' confrontata con tutte le precedenti della stessa piattaforma`,
    definizioni: {
      menzioni: "recensioni che esprimono un giudizio sull'aspetto (al massimo 1 per recensione)",
      pct_recensioni_che_lo_apprezzano: "recensioni con giudizio positivo sull'aspetto / recensioni aggregate del periodo x 100",
      pct_recensioni_che_lo_criticano: "recensioni con giudizio negativo sull'aspetto / recensioni aggregate del periodo x 100",
      pct_positive_su_menzioni: "giudizi positivi / menzioni x 100",
      pct_negative_su_menzioni: "giudizi negativi / menzioni x 100",
      saldo: '(positive - negative) / menzioni, da -1 a +1',
      piu_apprezzati: 'ordinati per numero di recensioni che apprezzano l\'aspetto',
      piu_criticati: 'ordinati per numero di recensioni che criticano l\'aspetto',
      per_tasso: `ordinati per quota sulle menzioni, solo aspetti con almeno ${minM} menzioni`,
      per_lingua: 'ogni lingua con almeno 15 recensioni contro tutte le altre, quota di recensioni negative o miste; significativo dopo Benjamini-Hochberg (FDR 10%)',
      andamento: 'ultimo periodo contro i precedenti; significativo = test su due proporzioni con correzione Benjamini-Hochberg (FDR 10%)',
    },
  },
  sentiment_complessivo: contaSentiment(valide),
  voto_medio: media(valide.filter((r) => r.rating !== null).map((r) => r.rating)),
  lingue,
  per_lingua: perLingua,
  aspetti: Object.values(statTotali),
  classifiche,
  periodi,
  andamento,
  per_piattaforma: perPiattaforma,
  serie_annuale: serieAnnuale,
  segnalazioni,
  controllo_campagne: campagne,
  avviso_a_grappolo: grappoli,
  periodi_di_calendario: periodiCalendario,
};

return [{ json: { aggregazione, info_analisi: infoAnalisi } }];

// AGGIORNAMENTO AUTOMATICO DELL'ELENCO DEGLI ASPETTI
// L'elenco fisso non cambia da solo da un giro all'altro, ma non e' chiuso per sempre.
// Se l'aggregazione dice che va rivisto (temi fuori elenco oltre la linea di base, o un
// tema fuori elenco in almeno il 2% delle recensioni), questo nodo:
// 1. chiede al modello una nuova versione: gli aspetti esistenti restano identici e
//    possono solo ricevere temi nuovi; si aggiungono aspetti nuovi solo per temi distinti;
//    i temi che non sono aspetti (giudizi generici come "bella app") vengono scartati con il motivo;
//    Per ogni tema candidato il modello riceve anche le prove: quante recensioni lo citano,
//    quali aspetti esistenti hanno gia' ricevuto quelle recensioni, qualche esempio;
// 2. controlla la proposta con regole fissate prima: aspetti esistenti invariati, nessun
//    tema in due aspetti, ogni tema candidato coperto o scartato, al massimo 5 aspetti nuovi,
//    nessun tema inventato (un aspetto nuovo contiene solo temi visti nelle recensioni),
//    nessun aspetto nuovo sovrapposto: se la meta' o piu' delle sue recensioni ha gia' uno
//    stesso aspetto esistente, il tema fa parte di quell'aspetto e non e' un aspetto nuovo;
// 3. fa un test di stabilita' stratificato: rianalizza con il vecchio e con il nuovo elenco
//    meta' campione a caso e meta' recensioni che citano i temi candidati (e' li' che un
//    aspetto nuovo puo' "rubare" recensioni ai vecchi). Il test va superato in tutti e due gli strati.
//    Sugli aspetti che esistevano gia' l'accordo con il giro corrente deve restare al livello
//    della variabilita' normale del modello (stesso elenco rianalizzato due volte), con una
//    tolleranza di 2 errori standard. Se il nuovo elenco "ruba" recensioni ai vecchi aspetti,
//    l'accordo cala e la proposta viene scartata;
// 4. se tutto passa, prepara la nuova versione (adottata dal giro successivo, che rianalizza
//    lo storico); altrimenti tiene la vecchia e chiede l'intervento di una persona.
// Se la versione in uso non ha ancora una linea di base, la misura in questo giro.
const helpers = this.helpers;
const usoToken = [];
const cfg = $('Configurazione').first().json;
const tax = $('Valida tassonomia').first().json;
const ingresso = $input.first().json;
const A = ingresso.aggregazione;
const ea = A.meta.elenco_aspetti;
const analisi = $('Valida e completa').all().map((i) => i.json);
const recensioni = new Map($('Recensioni pronte').all().map((i) => [i.json.review_id, i.json]));
const valide = analisi.filter((r) => ['ok', 'ritentata'].includes(r.stato) && !r.sospetta);

const rapporto = { versione_in_uso: tax.versione_aspetti, revisione_forzata_per_prova: !!cfg.forza_revisione_elenco && !ea.da_rivedere, controllo: { da_rivedere: ea.da_rivedere, temi_candidati: ea.temi_candidati, confronto_con_la_linea_di_base: ea.confronto_con_la_linea_di_base } };
let nuovoElenco = null;      // contenuto del file della nuova versione, se adottata
let lineaDiBase = null;      // linea di base da scrivere nell'elenco in uso, se mancava

// --- linea di base: se la versione in uso non ce l'ha, si misura adesso
// (dal 17/11 per piattaforma e lingua, senza i temi generici: la misura la fa l'Aggregazione; una linea di base
// nel formato vecchio, unica per tutto l'archivio, si rimisura e resta scritta come «precedente»)
if (tax.origine_aspetti === 'elenco fisso' && !tax.linea_di_base?.per_gruppo) {
  lineaDiBase = {
    per_gruppo: ea.misura_per_gruppo,
    dati_fino_al: ea.dati_fino_al,
    misurata_il: new Date().toISOString().slice(0, 10),
    giro: 'primo giro della versione ' + tax.versione_aspetti + (tax.linea_di_base ? ' con la linea di base per piattaforma e lingua' : ''),
    regola: 'gruppi piattaforma|lingua; temi generici esclusi; si confrontano poi solo le recensioni pubblicate dopo dati_fino_al',
    precedente: tax.linea_di_base ?? null,
  };
  rapporto.linea_di_base_misurata = lineaDiBase;
}

async function chiama(body) {
  const res = await helpers.httpRequest({
    method: 'POST', url: cfg.base_url + '/chat/completions',
    headers: { Authorization: 'Bearer ' + $env.OPENAI_API_KEY }, body, json: true, timeout: 240000,
  });
  if (res.usage) usoToken.push(res.usage);
  return res.choices?.[0]?.message?.content ?? '';
}

if (tax.origine_aspetti !== 'elenco fisso') {
  rapporto.esito = 'non applicabile: gli aspetti di questo giro vengono dalla scoperta, non da un elenco fisso';
} else if (!ea.da_rivedere && !cfg.forza_revisione_elenco) {
  rapporto.esito = 'nessun aggiornamento: il controllo non e\' scattato';
} else if (cfg.aggiorna_elenco === false) {
  rapporto.esito = 'aggiornamento sospeso per questo giro (AGGIORNA_ELENCO=false): il controllo e\' scritto qui sopra, decide una persona';
} else {
  // --- temi candidati: quelli del controllo, oppure i piu' frequenti fuori elenco
  const conteggio = new Map();
  for (const r of valide) for (const u of new Set(r.unmapped ?? [])) conteggio.set(u, (conteggio.get(u) ?? 0) + 1);
  const sogliaMinima = Math.max(3, Math.ceil(0.01 * valide.length));
  const candidati = (ea.temi_candidati.length ? ea.temi_candidati.map((c) => c.tema) : [...conteggio].filter(([, n]) => n >= sogliaMinima).sort((a, b) => b[1] - a[1]).slice(0, 20).map(([t]) => t));
  // prove per ogni tema: recensioni che lo citano e aspetti esistenti che hanno gia' ricevuto
  const nomeAspetto = new Map(tax.aspetti.map((a) => [a.aspect, a.nome]));
  const conTema = (temi) => valide.filter((r) => (r.unmapped ?? []).some((u) => temi.includes(u)));
  const coPresenza = (lista) => {
    const n = new Map();
    for (const r of lista) for (const a of new Set(r.aspects.map((x) => x.aspect))) n.set(a, (n.get(a) ?? 0) + 1);
    return [...n].sort((a, b) => b[1] - a[1]).map(([aspect, k]) => ({ aspect, recensioni: k, pct: Math.round((1000 * k) / lista.length) / 10 }));
  };
  rapporto.temi_proposti_al_modello = candidati.map((t) => {
    const lista = conTema([t]);
    const esempi = lista.slice(0, 3).map((r) => { const x = recensioni.get(r.review_id); return `${x.title} - ${x.text}`.slice(0, 200); });
    return { tema: t, recensioni: lista.length, aspetti_esistenti_gia_presenti: coPresenza(lista).slice(0, 3), esempi };
  });

  if (!candidati.length) {
    rapporto.esito = 'nessun aggiornamento: nessun tema fuori elenco abbastanza frequente da proporre';
  } else {
    // --- 1. proposta del modello
    const vecchi = tax.aspetti;
    const SYSTEM = `You maintain the FIXED list of aspects used to analyse reviews for ${$('Valida contesto').first().json.lettori_dei_risultati}.
Some topics judged by many reviews are not covered by the list. Propose only the CHANGES, with these rules:
- Existing aspects keep their identifier, name and description: you cannot change or remove them. You may only add candidate topics to their includes (in "added_to_existing").
- Each candidate topic comes with evidence: how many reviews mention it, the share of those reviews that already received each existing aspect, and a few examples.
- If half or more of a topic's reviews already received the same existing aspect, the topic is part of that aspect: add it to that aspect's includes, or discard it. Do not create a new aspect for it.
- Add a new aspect only for a topic that is a distinct theme that the readers can act on, clearly different from every existing aspect. At most 5 new aspects.
- The includes of a new aspect may contain only candidate topics. Do not invent topics that are not in the candidates.
- Overall judgements, positive or negative (for example "general praise", "bad app"), are not aspects: discard them.
- Every candidate topic must end up in exactly one place: "added_to_existing" (with the identifier of the existing aspect), the includes of one of the "new_aspects", or "discarded" with a short reason.
- For new aspects give: aspect (English snake_case), name_it (short, in Italian), description_it (one sentence in Italian saying what it covers and what it does not cover), includes.
- Empty lists are fine: if no change is needed, everything goes in "discarded".`;
    const utente = JSON.stringify({ aspetti_esistenti: vecchi.map((a) => ({ aspect: a.aspect, name_it: a.nome, description_it: a.descrizione, includes: a.temi_raggruppati })), temi_candidati: rapporto.temi_proposti_al_modello });
    // il modello restituisce solo le modifiche; l'elenco completo lo ricostruisce il codice
    // (correzione del 14/11: chiedere di ricopiare tutti gli aspetti esistenti faceva fallire la proposta
    // quando il modello restituiva solo quelli cambiati)
    const SCHEMA = { type: 'object', additionalProperties: false, required: ['added_to_existing', 'new_aspects', 'discarded'], properties: {
      added_to_existing: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['aspect', 'topics'], properties: { aspect: { type: 'string' }, topics: { type: 'array', items: { type: 'string' } } } } },
      new_aspects: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['aspect', 'name_it', 'description_it', 'includes'], properties: { aspect: { type: 'string' }, name_it: { type: 'string' }, description_it: { type: 'string' }, includes: { type: 'array', items: { type: 'string' } } } } },
      discarded: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['topic', 'reason'], properties: { topic: { type: 'string' }, reason: { type: 'string' } } } },
    } };
    let proposta = null;
    try {
      proposta = JSON.parse(await chiama({ model: cfg.model, temperature: 0, seed: cfg.seed, max_tokens: 8000,
        response_format: { type: 'json_schema', json_schema: { name: 'aspects_update', strict: true, schema: SCHEMA } },
        messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: utente }] }));
    } catch (e) {
      rapporto.errore_proposta = e.message;
    }

    // --- 2. controlli sulla proposta
    const problemi = [];
    let elencoProposto = null;
    if (!proposta) problemi.push('proposta del modello non leggibile');
    else {
      const normId = (x) => String(x).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
      const normT = (t) => String(t).toLowerCase().trim();
      // temi aggiunti agli aspetti esistenti: l'aspetto deve esistere e i temi devono essere stati visti fuori elenco
      const aggiunte = new Map();
      for (const x of proposta.added_to_existing ?? []) {
        const id = normId(x.aspect);
        if (!vecchi.some((v) => v.aspect === id)) { problemi.push(`temi aggiunti a un aspetto che non esiste: ${x.aspect}`); continue; }
        const temi = (x.topics ?? []).map(normT);
        const inventati = temi.filter((t) => !conteggio.has(t));
        if (inventati.length) problemi.push(`temi mai visti nelle recensioni aggiunti a ${id}: ${inventati.join(', ')}`);
        aggiunte.set(id, [...(aggiunte.get(id) ?? []), ...temi]);
      }
      // aspetti esistenti: identificativo, nome e descrizione restano quelli di prima, ricevono solo i temi
      elencoProposto = vecchi.map((v) => ({ aspect: v.aspect, nome: v.nome, descrizione: v.descrizione, temi_raggruppati: [...new Set([...v.temi_raggruppati, ...(aggiunte.get(v.aspect) ?? [])])] }));
      const nuovi = (proposta.new_aspects ?? []).map((a) => [normId(a.aspect), a]);
      for (const [id] of nuovi) if (vecchi.some((v) => v.aspect === id)) problemi.push(`l'aspetto nuovo ${id} ha lo stesso identificativo di uno esistente`);
      if (nuovi.length > 5) problemi.push(`troppi aspetti nuovi (${nuovi.length}, massimo 5)`);
      rapporto.sovrapposizione_aspetti_nuovi = [];
      for (const [id, p] of nuovi) {
        if (!/^[a-z][a-z0-9_]*$/.test(id)) problemi.push(`identificativo non valido: ${id}`);
        const temi = [...new Set(p.includes.map((t) => String(t).toLowerCase().trim()))];
        elencoProposto.push({ aspect: id, nome: String(p.name_it).trim(), descrizione: String(p.description_it).trim(), temi_raggruppati: temi, nuovo: true });
        // nessun tema inventato: ogni tema di un aspetto nuovo deve essere stato visto fuori elenco
        const inventati = temi.filter((t) => !conteggio.has(t));
        if (inventati.length) problemi.push(`l'aspetto nuovo ${id} contiene temi mai visti nelle recensioni: ${inventati.join(', ')}`);
        // nessuna sovrapposizione: le sue recensioni non devono gia' avere, per la maggior parte, uno stesso aspetto esistente
        const lista = conTema(temi);
        const top = coPresenza(lista)[0] ?? null;
        rapporto.sovrapposizione_aspetti_nuovi.push({ aspect: id, recensioni: lista.length, aspetto_esistente_piu_presente: top });
        if (top && top.pct >= 50) problemi.push(`l'aspetto nuovo ${id} si sovrappone a "${nomeAspetto.get(top.aspect) ?? top.aspect}": ${top.recensioni} delle sue ${lista.length} recensioni (${top.pct}%) hanno gia' quell'aspetto`);
      }
      const visti = new Map();
      for (const a of elencoProposto) for (const t of a.temi_raggruppati) {
        if (visti.has(t) && visti.get(t) !== a.aspect) problemi.push(`il tema "${t}" e' in due aspetti (${visti.get(t)} e ${a.aspect})`);
        visti.set(t, a.aspect);
      }
      const scartati = new Map((proposta.discarded ?? []).map((d) => [String(d.topic).toLowerCase().trim(), String(d.reason).trim()]));
      for (const c of candidati) if (!visti.has(c) && !scartati.has(c)) problemi.push(`il tema candidato "${c}" non e' ne' coperto ne' scartato`);
      if (elencoProposto.length > 20) problemi.push(`elenco troppo lungo (${elencoProposto.length} aspetti, massimo 20)`);
      rapporto.proposta = {
        aspetti_nuovi: nuovi.map(([id, p]) => ({ aspect: id, nome: p.name_it, temi: p.includes })),
        temi_aggiunti_ad_aspetti_esistenti: elencoProposto.filter((a) => !a.nuovo).map((a) => ({ aspect: a.aspect, temi_nuovi: a.temi_raggruppati.filter((t) => !vecchi.find((v) => v.aspect === a.aspect).temi_raggruppati.includes(t)) })).filter((x) => x.temi_nuovi.length),
        temi_scartati: [...scartati].map(([tema, motivo]) => ({ tema, motivo })),
      };
      rapporto.temi_non_aspetti_nuovi = [...scartati.keys()];
      // temi che cambiano davvero l'elenco (entrano in un aspetto): solo loro possono spostare recensioni
      rapporto.temi_che_entrano_nell_elenco = candidati.filter((c) => visti.has(c) && !scartati.has(c));
      // aspetti esistenti che ricevono temi nuovi: per loro un cambiamento e' voluto, non un furto
      rapporto.aspetti_esistenti_che_ricevono_temi = (rapporto.proposta.temi_aggiunti_ad_aspetti_esistenti ?? []).map((x) => x.aspect);
    }

    // la proposta cambia gli aspetti? Se scarta soltanto (es. giudizi generici) gli aspetti restano
    // identici: niente test di stabilita', niente nuova versione, niente rianalisi dello storico
    const cambiaAspetti = !!proposta && ((rapporto.proposta?.aspetti_nuovi ?? []).length > 0 || (rapporto.proposta?.temi_aggiunti_ad_aspetti_esistenti ?? []).length > 0);

    // --- 3. test di stabilita' (solo se la proposta passa i controlli e cambia gli aspetti)
    if (!problemi.length && cambiaAspetti) {
      // campione stratificato: fino a 30 recensioni che citano i temi che ENTRANO nell'elenco
      // (i temi scartati non cambiano nulla) + 30 a caso tra le altre
      const perOrdine = (a, b) => (recensioni.get(a.review_id)?.ordine_hash ?? '').localeCompare(recensioni.get(b.review_id)?.ordine_hash ?? '');
      const temiStrato = rapporto.temi_che_entrano_nell_elenco.length ? rapporto.temi_che_entrano_nell_elenco : candidati;
      const stratoTemi = conTema(temiStrato).sort(perOrdine).slice(0, 30);
      const idStrato = new Set(stratoTemi.map((r) => r.review_id));
      const stratoCaso = valide.filter((r) => !idStrato.has(r.review_id)).sort(perOrdine).slice(0, 30);
      const campione = [...stratoTemi, ...stratoCaso];
      // si controllano gli aspetti esistenti che NON ricevono temi nuovi: devono restare come prima
      const ricevono = new Set(rapporto.aspetti_esistenti_che_ricevono_temi);
      const idVecchi = new Set(tax.aspetti.map((a) => a.aspect).filter((a) => !ricevono.has(a)));
      const payload = (r) => { const x = recensioni.get(r.review_id); return { review_id: r.review_id, rating: x.rating, title: x.title, text: x.text || x.title }; };
      // istruzioni dell'analisi con un elenco diverso: si sostituisce solo la parte degli aspetti
      const istruzioniCon = (elenco) => {
        const testo = elenco.map((a) => `- ${a.aspect}: ${a.descrizione} Includes: ${a.temi_raggruppati.slice(0, 25).join(', ')}.`).join('\n');
        const system = tax.system_prompt.replace(/Aspects:\n[\s\S]*?\n\nAttention categories:/, `Aspects:\n${testo}\n\nAttention categories:`);
        const body = JSON.parse(JSON.stringify(tax.body_base));
        body.response_format.json_schema.schema.properties.results.items.properties.aspects.items.properties.aspect.enum = elenco.map((a) => a.aspect);
        return { system, body };
      };
      async function rianalizza(elenco) {
        const { system, body } = istruzioniCon(elenco);
        const out = new Map();
        for (let i = 0; i < campione.length; i += cfg.batch_size) {
          const gruppo = campione.slice(i, i + cfg.batch_size);
          try {
            const testo = await chiama({ ...body, messages: [{ role: 'system', content: system }, { role: 'user', content: JSON.stringify(gruppo.map(payload)) }] });
            for (const g of JSON.parse(testo).results ?? []) out.set(g.review_id, g.aspects ?? []);
          } catch (e) { /* recensione mancante: conta come disaccordo */ }
        }
        return out;
      }
      // accordo sugli aspetti vecchi: coppie (recensione, aspetto vecchio) presenti in almeno uno dei due,
      // uguali se l'aspetto c'e' in entrambi con lo stesso giudizio
      const accordo = (nuove, gruppo) => {
        let uguali = 0, totale = 0;
        for (const r of gruppo) {
          const prima = new Map(r.aspects.filter((a) => idVecchi.has(a.aspect)).map((a) => [a.aspect, a.sentiment]));
          const dopo = new Map((nuove.get(r.review_id) ?? []).filter((a) => idVecchi.has(a.aspect)).map((a) => [a.aspect, a.sentiment]));
          for (const k of new Set([...prima.keys(), ...dopo.keys()])) { totale++; if (prima.get(k) === dopo.get(k)) uguali++; }
        }
        return { uguali, totale, pct: totale ? Math.round((1000 * uguali) / totale) / 10 : null };
      };
      const rianalisiVecchio = await rianalizza(tax.aspetti);
      const rianalisiNuovo = await rianalizza(elencoProposto);
      // il nuovo elenco non deve far calare l'accordo oltre 2 errori standard rispetto alla variabilita' normale
      // (l'accordo con il vecchio elenco misura la variabilita' normale di questa rianalisi; non e' un test-retest puro,
      // perche' le istruzioni vengono ricostruite: il test-retest vero, due giri identici, e' 93% sulle coppie recensione-aspetto)
      const confronta = (gruppo) => {
        const v = accordo(rianalisiVecchio, gruppo), n = accordo(rianalisiNuovo, gruppo);
        if (!v.totale || !n.totale) return { recensioni: gruppo.length, accordo_rianalizzando_con_il_vecchio_elenco: v, accordo_rianalizzando_con_il_nuovo_elenco: n, z_nuovo_meno_vecchio: null, superato: true, dati_sufficienti: false };
        const p0 = v.uguali / v.totale, p1 = n.uguali / n.totale;
        const pp = (v.uguali + n.uguali) / (v.totale + n.totale);
        const se = Math.sqrt(pp * (1 - pp) * (1 / v.totale + 1 / n.totale));
        const z = se > 0 ? Math.round((100 * (p1 - p0)) / se) / 100 : 0;
        return { recensioni: gruppo.length, accordo_rianalizzando_con_il_vecchio_elenco: v, accordo_rianalizzando_con_il_nuovo_elenco: n, z_nuovo_meno_vecchio: z, superato: z > -2, dati_sufficienti: v.totale >= 20 && n.totale >= 20 };
      };
      const strati = { recensioni_con_temi_candidati: confronta(stratoTemi), recensioni_a_caso: confronta(stratoCaso) };
      rapporto.test_di_stabilita = {
        recensioni_nel_campione: campione.length,
        strati,
        aspetti_controllati: [...idVecchi],
        regola: "superato se, in ciascuno dei due strati, l'accordo sugli aspetti esistenti che non ricevono temi nuovi non scende, con il nuovo elenco, di oltre 2 errori standard rispetto a quello con il vecchio elenco (variabilita' normale del modello). Con un aspetto nuovo servono almeno 20 coppie recensione-aspetto nello strato dei temi: con meno il test non ha la potenza per vedere un furto di recensioni",
        superato: Object.values(strati).every((x) => x.superato),
      };
      for (const [nome, x] of Object.entries(strati)) if (!x.superato) problemi.push(`test di stabilita' non superato (${nome.replace(/_/g, ' ')}): l'accordo sugli aspetti esistenti scende dal ${x.accordo_rianalizzando_con_il_vecchio_elenco.pct}% al ${x.accordo_rianalizzando_con_il_nuovo_elenco.pct}% (z = ${x.z_nuovo_meno_vecchio})`);
      if ((rapporto.proposta.aspetti_nuovi ?? []).length && !strati.recensioni_con_temi_candidati.dati_sufficienti) {
        rapporto.test_di_stabilita.superato = false;
        problemi.push(`test di stabilita' non conclusivo: nello strato dei temi ci sono solo ${strati.recensioni_con_temi_candidati.accordo_rianalizzando_con_il_vecchio_elenco.totale} coppie recensione-aspetto (ne servono almeno 20 per adottare un aspetto nuovo)`);
      }
    }

    // --- 4. decisione
    if (problemi.length) {
      rapporto.esito = 'proposta scartata: resta la versione in uso, serve l\'intervento di una persona';
      rapporto.problemi = problemi;
    } else if (!cambiaAspetti) {
      // stessa versione: si registrano solo i temi che non sono aspetti; la linea di base va rimisurata,
      // perche' quei temi non contano piu' come fuori elenco
      let inUso = null;
      try { inUso = $('Estrai elenco fisso').first().json.data ?? null; } catch (e) { inUso = null; }
      const aggiunti = (rapporto.temi_non_aspetti_nuovi ?? []).filter((t) => !(tax.temi_non_aspetti ?? []).includes(t));
      if (inUso && aggiunti.length) {
        nuovoElenco = {
          ...inUso,
          linea_di_base_temi_fuori_elenco: null, // si rimisura al prossimo giro
          temi_non_aspetti: [...(tax.temi_non_aspetti ?? []), ...aggiunti],
          aggiornamenti_senza_cambio_aspetti: [...(inUso.aggiornamenti_senza_cambio_aspetti ?? []), { data: new Date().toISOString().slice(0, 10), temi_non_aspetti_aggiunti: aggiunti, scartati: rapporto.proposta.temi_scartati }],
        };
        rapporto.esito = `aspetti invariati, resta la versione ${tax.versione_aspetti}: registrati come non aspetti ${aggiunti.join(', ')}; la linea di base si rimisura al prossimo giro`;
      } else {
        rapporto.esito = `aspetti invariati, resta la versione ${tax.versione_aspetti}: i temi candidati sono gia' registrati come non aspetti`;
      }
      rapporto.rianalisi_dello_storico_necessaria = false;
    } else {
      const numero = (parseInt(String(tax.versione_aspetti).replace(/\D/g, ''), 10) || 1) + 1;
      nuovoElenco = {
        versione: 'v' + numero,
        creato_il: new Date().toISOString().slice(0, 10),
        origine: `aggiornamento automatico della ${tax.versione_aspetti}`,
        modifiche_rispetto_alla_versione_precedente: rapporto.proposta,
        controlli_superati: { test_di_stabilita: rapporto.test_di_stabilita },
        linea_di_base_temi_fuori_elenco: null, // si misura al primo giro della nuova versione
        temi_non_aspetti: [...new Set([...(tax.temi_non_aspetti ?? []), ...(rapporto.temi_non_aspetti_nuovi ?? [])])],
        aspetti: elencoProposto.map(({ nuovo, ...a }) => a),
      };
      rapporto.esito = `nuova versione ${nuovoElenco.versione} adottata: la usa il prossimo giro, che rianalizza tutte le recensioni con il nuovo elenco`;
      rapporto.rianalisi_dello_storico_necessaria = true;
    }
  }
}
rapporto.uso_token = usoToken;

return [{ json: { ...ingresso, aggiornamento_elenco: rapporto, nuovo_elenco: nuovoElenco, linea_di_base_misurata: lineaDiBase } }];

// FATTI PER IL DIGEST
// Il codice calcola i fatti e scrive le frasi con i numeri. Il modello riceve i
// fatti e restituisce solo commenti a parole (senza cifre) e citazioni: il digest
// lo monta il nodo "Verifica digest", che inserisce le frasi con i numeri.
const cfg = $('Configurazione').first().json;
const ctx = $('Valida contesto').first().json;
const A = $input.first().json.aggregazione;
const recensioni = new Map($('Recensioni pronte').all().map((i) => [i.json.review_id, i.json]));
const analisi = new Map($('Valida e completa').all().map((i) => [i.json.review_id, i.json]));

const intero = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const perc = (x) => (x === null || x === undefined ? null : x > 0 && x < 1 ? String(x).replace('.', ',') + '%' : Math.round(x) + '%');
const dec = (x) => String(x).replace('.', ',');
const nome = (id) => A.aspetti.find((a) => a.aspect === id)?.nome ?? id;

const NOMI_PERSONA = /\b(Mr|Mrs|Ms|Miss|Mme|Dr|Sr|Sra|Herr|Frau|Sig|Signor|Signora)\.?\s+[A-Z][a-z]+/;

function candidati(aspect, sentimentAspetto, overallAmmessi, quanti) {
  const lista = [];
  for (const r of analisi.values()) {
    if (r.sospetta || !['ok', 'ritentata'].includes(r.stato)) continue;
    if (!overallAmmessi.includes(r.overall_sentiment)) continue;
    if (!r.aspects.some((x) => x.aspect === aspect && x.sentiment === sentimentAspetto)) continue;
    const rec = recensioni.get(r.review_id);
    if (!rec || rec.text.length < 80 || rec.text.length > 700 || NOMI_PERSONA.test(rec.text)) continue;
    if (/<[A-Z_]+>/.test(rec.text)) continue; // testi con dati oscurati: meglio non citarli
    lista.push({ r, rec });
  }
  // prima l'inglese (leggibile dalla direzione), poi le piu' recenti
  lista.sort((a, b) => (a.r.language === 'en' ? 0 : 1) - (b.r.language === 'en' ? 0 : 1) || (b.rec.published_date ?? '').localeCompare(a.rec.published_date ?? ''));
  return lista.slice(0, quanti).map(({ r, rec }) => ({
    review_id: r.review_id,
    data: rec.published_date,
    voto: `${rec.rating} su ${ctx.voto.massimo}`,
    lingua: r.language,
    testo: rec.text,
  }));
}

const top = (lista, n) => lista.slice(0, n);

// articolo davanti a una percentuale (il 12%, l'11%, lo 0,4%) e preposizioni articolate
function art(p) {
  const n = String(p);
  if (/^0/.test(n)) return 'lo ' + n;
  if (/^(8|11(?![\d])|1(?![\d])|1,)/.test(n)) return "l'" + n;
  return 'il ' + n;
}
function prep(p, base) {
  const a = art(p);
  const forme = { da: { 'il ': 'dal ', "l'": "dall'", 'lo ': 'dallo ' }, a: { 'il ': 'al ', "l'": "all'", 'lo ': 'allo ' } };
  for (const [k, v] of Object.entries(forme[base])) if (a.startsWith(k)) return v + a.slice(k.length);
  return a;
}
const misuraTesto = (m) => (m === 'pct_recensioni_che_lo_criticano' ? 'negativo' : 'positivo');

// la prova di una segnalazione e' stata accettata anche se quasi identica al testo:
// al digest si passa invece la frase ESATTA del testo che le somiglia di piu',
// cosi' il modello puo' citarla parola per parola
function provaEsatta(evidenza, testo) {
  if (!evidenza || !testo) return null;
  const pulito = (s) => s.toLowerCase().replace(/\s+/g, ' ').trim();
  if (pulito(testo).includes(pulito(evidenza))) {
    const i = pulito(testo).indexOf(pulito(evidenza));
    // ricostruisce lo stesso pezzo con gli spazi originali
    const testoSpazi = testo.replace(/\s+/g, ' ');
    return testoSpazi.slice(i, i + pulito(evidenza).length).trim();
  }
  const parole = new Set(pulito(evidenza).match(/[\p{L}\p{N}]+/gu) ?? []);
  const frasi = testo.split(/(?<=[.!?])\s+|\n+/).map((f) => f.replace(/\s+/g, ' ').trim()).filter((f) => f.length > 10);
  let migliore = null, punti = 0;
  for (const f of frasi) {
    const p = (pulito(f).match(/[\p{L}\p{N}]+/gu) ?? []).filter((w) => parole.has(w)).length;
    if (p > punti) { punti = p; migliore = f; }
  }
  return migliore ? migliore.split(' ').slice(0, 30).join(' ') : null;
}

// parole che indicano l'aspetto in una frase (dai temi raggruppati): servono a
// scegliere, nel digest di riserva, una frase che parla davvero di quell'aspetto
const tassonomia = $('Valida tassonomia').first().json.aspetti;
function paroleChiave(aspect) {
  const a = tassonomia.find((x) => x.aspect === aspect);
  const parole = [...(a?.temi_raggruppati ?? []), aspect.replace(/_/g, ' ')].join(' ').toLowerCase().match(/[a-z]{4,}/g) ?? [];
  const generiche = new Set(['quality', 'service', 'services', 'experience', 'overall', 'general', 'level', 'value']);
  return [...new Set(parole)].filter((p) => !generiche.has(p));
}
const S = A.sentiment_complessivo;
const anni = [A.meta.prima_data?.slice(0, 4), A.meta.ultima_data?.slice(0, 4)];
// periodo: con un anno solo si scrivono le date (correzione del 14/11: «dal 2026 al 2026»)
const dataIt = (d) => (d ? `${d.slice(8, 10)}/${d.slice(5, 7)}/${d.slice(0, 4)}` : '');
const periodoTesto = anni[0] === anni[1] ? `tra il ${dataIt(A.meta.prima_data)} e il ${dataIt(A.meta.ultima_data)}` : `dal ${anni[0]} al ${anni[1]}`;
// lingue: il confronto ha senso solo con almeno due lingue con abbastanza recensioni
const lingueConfrontate = A.per_lingua.filter((l) => l.confronto_con_le_altre_lingue).length >= 2;
// «divisivo» = pareri spaccati tra chi ne parla: tra il 30% e il 70% di giudizi negativi. Correzione: prima
// era «almeno il 30%», e un aspetto criticato da quasi tutti risultava «divisivo»
const SOGLIA_DIVISIVO = 30, SOGLIA_DIVISIVO_MAX = 70;
// «apprezzati»: solo aspetti con piu' giudizi positivi che negativi tra chi ne parla (prima un aspetto positivo
// solo per pochi compariva tra gli apprezzati, perche' la classifica e' per numero di recensioni positive)
const negativeSu = new Map(A.aspetti.map((a) => [a.aspect, a.pct_negative_su_menzioni ?? 0]));
const apprezzatiVeri = A.classifiche.piu_apprezzati.filter((x) => (x.pct_positive_su_menzioni ?? 0) > (negativeSu.get(x.aspect) ?? 0));
// lingue: nomi in italiano; «und» (non riconosciuta) non e' una lingua
const NOME_LINGUA = { it: 'italiano', en: 'inglese', es: 'spagnolo', fr: 'francese', de: 'tedesco', pt: 'portoghese', ro: 'rumeno' };
// recensioni da guardare negli ultimi AVVISI_GIORNI giorni (come nel messaggio Telegram)
const giornoN = (d) => Math.round(Date.parse(String(d).slice(0, 10) + 'T00:00:00Z') / 86400000);
const oggiN = giornoN(cfg.grappolo_oggi ?? new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Rome' }));
const daGuardareRecenti = [...analisi.values()].filter((r) => r.needs_attention && r.stato !== 'duplicato' && r.published_date && oggiN - giornoN(r.published_date) < (cfg.avvisi_giorni ?? 14));

const significativi = A.andamento.filter((x) => x.significativo);
const fatti = {
  // FRASI CON I NUMERI: le scrive il codice, il modello le copia identiche.
  // Cosi' un numero non puo' cambiare significato (es. una quota sul totale
  // presentata come quota su chi parla dell'aspetto).
  frase_sintesi: `Sono state analizzate ${intero(A.meta.recensioni_aggregate)} recensioni pubblicate ${periodoTesto}. Il voto medio delle recensioni scritte e' ${dec(A.voto_medio)} su ${ctx.voto.massimo} (non e' il voto dello store, che conta anche chi da' solo le stelle). ${art(perc(S.positive.pct)).replace(/^./, (c) => c.toUpperCase())} delle recensioni e' positivo, ${art(perc(S.mixed.pct))} misto, ${art(perc(S.negative.pct))} negativo e ${art(perc(S.neutral.pct))} neutro.`,
  // numeri senza ambiguita' che si possono ripetere anche fuori dalle frasi
  recensioni_analizzate: intero(A.meta.recensioni_aggregate),
  dal_anno: anni[0],
  al_anno: anni[1],
  escluse_dai_conteggi: A.meta.escluse_dall_aggregazione,
  aspetti_piu_apprezzati: top(apprezzatiVeri, 5).map((x) => ({
    aspetto: x.nome,
    frase_numeri: `${intero(x.recensioni_positive)} recensioni su ${intero(A.meta.recensioni_aggregate)} ne danno un giudizio positivo (${art(perc(x.pct_recensioni_che_lo_apprezzano))} del totale); tra le ${intero(x.menzioni)} recensioni che ne parlano, i giudizi positivi sono ${art(perc(x.pct_positive_su_menzioni))}`,
  })),
  aspetti_piu_criticati: top(A.classifiche.piu_criticati, 5).map((x) => ({
    aspetto: x.nome,
    frase_numeri: `${intero(x.recensioni_negative)} recensioni su ${intero(A.meta.recensioni_aggregate)} ne danno un giudizio negativo (${art(perc(x.pct_recensioni_che_lo_criticano))} del totale); tra le ${intero(x.menzioni)} recensioni che ne parlano, i giudizi negativi sono ${art(perc(x.pct_negative_su_menzioni))}`,
  })),
  lingue_confrontate: lingueConfrontate,
  // iOS e Android sempre separati: una frase per piattaforma, senza confronti tra le due
  frasi_piattaforme: (() => {
    const nomi = new Map(A.aspetti.map((a) => [a.aspect, a.nome]));
    const etichetta = { ios: 'iOS', android: 'Android' };
    const righe = A.per_piattaforma.map((p) => {
      const s = p.sentiment_complessivo;
      const critico = p.piu_criticati?.[0] ? `; l'aspetto piu' criticato e' ${nomi.get(p.piu_criticati[0]) ?? p.piu_criticati[0]}` : '';
      return `${etichetta[p.piattaforma] ?? p.piattaforma}: ${intero(p.recensioni)} recensioni, voto medio delle recensioni ${dec(p.voto_medio)}, ${art(perc(s.positive.pct))} positive e ${art(perc(s.negative.pct))} negative${critico}`;
    });
    if (!A.per_piattaforma.some((p) => p.piattaforma === 'android')) righe.push('Android: nessuna recensione in questo giro (le recensioni Android arrivano dalla Play Console)');
    return righe;
  })(),
  aspetti_piu_divisivi: top(A.classifiche.piu_criticati_per_tasso.filter((x) => x.pct_negative_su_menzioni >= SOGLIA_DIVISIVO && x.pct_negative_su_menzioni <= SOGLIA_DIVISIVO_MAX), 3).map((x) => ({
    aspetto: x.nome,
    frase_numeri: `tra le ${intero(x.menzioni)} recensioni che ne parlano, i giudizi negativi sono ${art(perc(x.pct_negative_su_menzioni))}`,
  })),
  periodi: A.periodi.map((p) => ({
    periodo: p.periodo,
    frase_numeri: `nel periodo ${p.periodo} (${intero(p.recensioni)} recensioni) il voto medio e' ${dec(p.voto_medio)} su ${ctx.voto.massimo}, con ${art(perc(p.sentiment_complessivo.positive.pct))} di recensioni positive e ${art(perc(p.sentiment_complessivo.negative.pct))} di negative` +
      // per lingua (17/11): la quota di inglese cambia nel tempo, il totale da solo inganna
      ((p.per_lingua ?? []).filter((l) => l.recensioni > 0).length > 1 ? ` (negative: ${(p.per_lingua ?? []).filter((l) => l.recensioni > 0).map((l) => `${NOME_LINGUA[l.lingua] ?? l.lingua} ${perc(l.pct_negative)} su ${intero(l.recensioni)}`).join(', ')})` : ''),
    piu_apprezzati: p.piu_apprezzati.slice(0, 3).map(nome),
    piu_criticati: p.piu_criticati.slice(0, 3).map(nome),
  })),
  // una sola frase per aspetto e per periodo di confronto, con critiche e apprezzamenti
  // insieme: il modello tende a unire due frasi sullo stesso aspetto, e cosi' non serve
  cambiamenti_significativi: (() => {
    const gruppi = new Map();
    for (const x of significativi) {
      const k = x.nome + '|' + x.periodo_di_confronto + '|' + x.lingua;
      if (!gruppi.has(k)) gruppi.set(k, { aspetto: x.nome, lingua: x.lingua, confronto: x.periodo_di_confronto, ultimo: x.ultimo_periodo, pezzi: [] });
      gruppi.get(k).pezzi.push(x);
    }
    return [...gruppi.values()].map((g) => {
      const pezzo = (x) => `le recensioni con giudizio ${misuraTesto(x.misura)} passano ${prep(perc(x.valore_periodo_di_confronto), 'da')} ${prep(perc(x.valore_ultimo_periodo), 'a')}`;
      const ordinati = [...g.pezzi].sort((a, b) => (a.misura < b.misura ? -1 : 1));
      return {
        aspetto: g.aspetto,
        frase_numeri: `${g.aspetto}, recensioni in ${NOME_LINGUA[g.lingua] ?? g.lingua}, dal ${g.confronto} al ${g.ultimo}: ${ordinati.map(pezzo).join(' e ')}`,
      };
    });
  })(),
  // numeri senza ambiguita', ammessi anche fuori dalle frasi
  confronti_nel_tempo_eseguiti: intero(A.andamento.length),
  confronti_nel_tempo_significativi: intero(significativi.length),
  frase_segnalate_recenti: `Negli ultimi ${cfg.avvisi_giorni ?? 14} giorni le recensioni da guardare sono ${intero(daGuardareRecenti.length)}: ${intero(daGuardareRecenti.filter((r) => (r.segnalazioni ?? []).length).length)} con un problema preciso, di cui ${intero(daGuardareRecenti.filter((r) => r.priorita === 'alta').length)} con priorita' alta.`,
  frase_segnalate: `In tutto l'archivio le recensioni segnalate sono ${intero(A.segnalazioni.totale)} (${art(perc(A.segnalazioni.pct_sul_totale))} del totale): ${intero(A.segnalazioni.per_priorita.alta)} con priorita' alta, ${intero(A.segnalazioni.per_priorita.media)} media e ${intero(A.segnalazioni.per_priorita.bassa)} bassa.`,
  frase_campagne: (() => {
    const c = A.controllo_campagne;
    if (!c) return null;
    const pezzi = [];
    if (c.testi_quasi_identici.length) {
      // solo i 3 gruppi piu' recenti, gli altri contati (prima erano elencati uno per uno)
      const g3 = [...c.testi_quasi_identici].sort((a, b) => String(b.al).localeCompare(String(a.al))).slice(0, 3);
      const altri = c.testi_quasi_identici.length - g3.length;
      pezzi.push(`${intero(c.testi_quasi_identici.length)} gruppi di recensioni con testi lunghi quasi identici (${altri > 0 ? 'i piu\' recenti: ' : ''}${g3.map((g) => `${intero(g.recensioni)} recensioni ${g.dal === g.al ? `il ${g.dal}` : `dal ${g.dal} al ${g.al}`}`).join('; ')}${altri > 0 ? `; gli altri ${intero(altri)} in aggregazione.json` : ''})`);
    }
    if (c.picchi_una_stella.length) pezzi.push(`giorni con un picco anomalo di recensioni da ${ctx.voto.minimo} stella: ${c.picchi_una_stella.map((p) => `${p.data}${p.piattaforma ? ' su ' + ({ ios: 'iOS', android: 'Android' }[p.piattaforma] ?? p.piattaforma) : ''} (${intero(p.una_stella)} contro ${dec(p.attese_una_stella)} attese)`).join('; ')}`);
    return pezzi.length
      ? `Controllo delle campagne coordinate: ${pezzi.join('; inoltre ')}. Possono essere campagne organizzate: vanno guardate da una persona.`
      : `Controllo delle campagne coordinate: nessun gruppo di testi lunghi quasi identici e nessun picco anomalo di recensioni da ${ctx.voto.minimo} stella.`;
  })(),
  segnalate_da_mostrare: A.segnalazioni.elenco.slice(0, 8).map((s) => ({
    review_id: s.review_id,
    data: s.published_date,
    voto: s.rating === null ? null : `${s.rating} su ${ctx.voto.massimo}`,
    priorita: s.priorita,
    motivo: s.attention_reason,
    prova: provaEsatta(analisi.get(s.review_id)?.segnalazioni?.[0]?.evidenza, recensioni.get(s.review_id)?.text),
  })),
  // per piattaforma e versione (solo se il file ha la versione dell'app)
  per_piattaforma: A.per_piattaforma.some((p) => p.versioni.length) ? A.per_piattaforma.map((p) => {
    const sig = p.andamento_ultima_versione.filter((x) => x.significativo);
    return {
      piattaforma: p.piattaforma,
      recensioni: intero(p.recensioni),
      voto_medio: p.voto_medio === null ? null : dec(p.voto_medio) + ' su ' + ctx.voto.massimo,
      positive: perc(p.sentiment_complessivo.positive.pct),
      negative: perc(p.sentiment_complessivo.negative.pct),
      piu_apprezzati: p.piu_apprezzati.slice(0, 3).map(nome),
      piu_criticati: p.piu_criticati.slice(0, 3).map(nome),
      // solo le ultime 5 versioni con abbastanza recensioni (prima il digest elencava decine di versioni);
      // tutte le versioni sono nel foglio Versioni dell'Excel
      versioni_non_mostrate: intero(p.versioni.length - Math.min(5, p.versioni.filter((v) => !v.sotto_il_minimo).length)),
      versioni: p.versioni.filter((v) => !v.sotto_il_minimo).slice(-5).map((v) => (v.sotto_il_minimo
        ? { versione: v.versione, recensioni: intero(v.recensioni), nota: 'troppe poche recensioni per avere statistiche' }
        : {
            versione: v.versione,
            recensioni: intero(v.recensioni),
            voto_medio: dec(v.voto_medio),
            positive: perc(v.sentiment_complessivo.positive.pct),
            negative: perc(v.sentiment_complessivo.negative.pct),
            piu_criticati: v.piu_criticati.map(nome),
          })),
      confronti_ultima_versione_eseguiti: intero(p.andamento_ultima_versione.length),
      cambiamenti_ultima_versione: sig.map((x) => ({
        aspetto: x.nome,
        lingua: NOME_LINGUA[x.lingua] ?? x.lingua,
        misura: x.misura === 'pct_recensioni_che_lo_criticano' ? 'quota di recensioni che lo criticano' : 'quota di recensioni che lo apprezzano',
        ultima_versione: x.ultima_versione,
        valore_ultima_versione: perc(x.valore_nuovo),
        confrontata_con: x.confrontata_con,
        valore_di_confronto: perc(x.valore_confronto),
        direzione: x.direzione,
      })),
    };
  }) : undefined,
  lingue_con_abbastanza_recensioni: A.per_lingua.filter((l) => l.confronto_con_le_altre_lingue).map((l) => ({
    lingua: l.lingua,
    recensioni: intero(l.recensioni),
    negative_o_miste: perc(l.confronto_con_le_altre_lingue.valore_lingua),
  })),
  frase_lingue: (() => {
    const l = A.per_lingua.filter((x) => x.lingua !== 'und' && x.confronto_con_le_altre_lingue);
    if (l.length < 2) return null;
    const pezzi = l.map((x) => `${NOME_LINGUA[x.lingua] ?? x.lingua} ${intero(x.recensioni)} recensioni, ${perc(x.confronto_con_le_altre_lingue.valore_lingua)} negative o miste`);
    const sig = l.some((x) => x.confronto_con_le_altre_lingue.significativo);
    return `Per lingua: ${pezzi.join('; ')}. ${sig ? 'La differenza tra le lingue è oltre il rumore statistico.' : 'Le differenze tra le lingue sono compatibili con il caso.'}`;
  })(),
  differenze_tra_lingue_significative: A.per_lingua.filter((l) => l.lingua !== 'und' && l.confronto_con_le_altre_lingue?.significativo).map((l) => ({
    lingua: l.lingua,
    frase_numeri: `nelle recensioni in lingua ${l.lingua} le negative o miste sono ${art(perc(l.confronto_con_le_altre_lingue.valore_lingua))}, contro ${art(perc(l.confronto_con_le_altre_lingue.valore_altre_lingue))} nelle altre lingue`,
  })),
  citazioni_disponibili: [
    ...top(apprezzatiVeri, 3).map((x) => ({ per: `apprezzato: ${x.nome}`, parole_chiave: paroleChiave(x.aspect), recensioni: candidati(x.aspect, 'positive', ['positive'], 3) })),
    ...top(A.classifiche.piu_criticati, 3).map((x) => ({ per: `criticato: ${x.nome}`, parole_chiave: paroleChiave(x.aspect), recensioni: candidati(x.aspect, 'negative', ['negative', 'mixed'], 3) })),
  ],
};

const SYSTEM = `Sei un analista che scrive per ${ctx.lettori_dei_risultati}: le recensioni riguardano ${ctx.oggetto_recensito} e sono scritte da ${ctx.autori_delle_recensioni}. Ricevi i fatti in JSON, gia' calcolati. I numeri, gli elenchi e i titoli li inserisce il sistema: tu scrivi SOLO i commenti a parole e scegli le citazioni, in ${ctx.lingua_del_digest} semplice, per chi non e' tecnico.

Restituisci un JSON con questi campi:
- In tutti i campi chiama il prodotto solo "l'app": non scrivere di che tipo di app si tratta ne' il suo settore.
- sintesi: da due a quattro frasi su che cosa emerge nel complesso (che cosa piace, che cosa si critica, come cambiano le cose). Se "lingue_confrontate" e' true, aggiungi una frase sulle lingue: se "differenze_tra_lingue_significative" e' vuoto, di' che le recensioni nelle diverse lingue non mostrano differenze distinguibili dal caso. Se e' false, non parlare di lingue.
- commento_apprezzati: due o tre frasi sugli aspetti in "aspetti_piu_apprezzati".
- commento_criticati: due o tre frasi sugli aspetti in "aspetti_piu_criticati" e "aspetti_piu_divisivi". Spiega la differenza tra un aspetto criticato da molte recensioni in assoluto e uno criticato da una parte grande di chi ne parla.
- commento_tempo: da due a quattro frasi sui "cambiamenti_significativi". Se e' vuoto, di' che i cambiamenti tra periodi non sono distinguibili dal caso. Parla solo dei cambiamenti significativi e non spiegarne le cause.
- commento_segnalate: da una a tre frasi sui temi delle recensioni da guardare.
- citazioni: da tre a sei citazioni, almeno una per la sezione "apprezzati", una per "criticati" e una per "segnalate". Per ognuna: sezione, review_id, testo copiato parola per parola da un campo "testo" o "prova" dei fatti (frasi consecutive, da 8 a 30 parole, che si capiscano da sole), traduzione in ${ctx.lingua_del_digest} (stringa vuota se la citazione e' gia' in ${ctx.lingua_del_digest}).

Regole obbligatorie:
1. Nei commenti NESSUNA cifra: niente numeri, percentuali, anni o conteggi. Descrivi a parole (per esempio "la maggior parte", "aumentano", "piu' di prima", "nell'ultimo periodo").
2. Nei commenti niente virgolette « »: le citazioni vanno solo nel campo "citazioni".
3. Nomi degli aspetti come scritti nei fatti.
4. Nessun nome di persona; non scegliere citazioni che ne contengono.
5. Affermazioni solo se stanno nei fatti: chiama "divisivo" solo un aspetto di "aspetti_piu_divisivi"; scrivi che le critiche a un aspetto aumentano, o che il suo apprezzamento cala, solo se quel cambiamento e' in "cambiamenti_significativi". Non attribuire cause o dettagli (per esempio di che cosa si lamentano) che i fatti non contengono. Il sistema controlla queste affermazioni.
5. Nessuna informazione che non sia nei fatti.`;

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['sintesi', 'commento_apprezzati', 'commento_criticati', 'commento_tempo', 'commento_segnalate', 'citazioni'],
  properties: {
    sintesi: { type: 'string' },
    commento_apprezzati: { type: 'string' },
    commento_criticati: { type: 'string' },
    commento_tempo: { type: 'string' },
    commento_segnalate: { type: 'string' },
    citazioni: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['sezione', 'review_id', 'testo', 'traduzione'],
        properties: {
          sezione: { type: 'string', enum: ['apprezzati', 'criticati', 'segnalate'] },
          review_id: { type: 'string' },
          testo: { type: 'string' },
          traduzione: { type: 'string' },
        },
      },
    },
  },
};

return [{
  json: {
    fatti,
    body: {
      model: cfg.model,
      temperature: 0,
      seed: cfg.seed,
      max_tokens: 2500,
      response_format: { type: 'json_schema', json_schema: { name: 'digest', strict: true, schema: SCHEMA } },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: JSON.stringify(fatti, null, 1) },
      ],
    },
  },
}];

// VERIFICA E COMPOSIZIONE DEL DIGEST
// Il digest lo monta il CODICE: titoli, frasi con i numeri (scritte nel nodo dei
// fatti), elenchi, recensioni da guardare. Dal modello arrivano solo i commenti a
// parole, sezione per sezione, e le citazioni. Cosi' ogni numero del digest e'
// scritto dal codice, per costruzione, e non puo' cambiare significato.
// Controlli sulla parte del modello:
// - nei commenti nessuna cifra e nessuna virgoletta « »;
// - ogni citazione copiata parola per parola dalla recensione indicata;
// - identificativi esistenti e almeno una citazione per le sezioni principali.
// - affermazioni a parole coerenti con i fatti (divisivi, critiche in aumento, apprezzamento in calo):
//   vedi controllaAffermazioni piu' sotto (aggiunto il 14/11 dopo la revisione del digest dell'hotel).
// Se un controllo fallisce, il modello riceve i problemi e corregge (fino a 2 volte).
// Se non basta, il digest esce senza i commenti del modello (versione di riserva).
const helpers = this.helpers;
const usoToken = []; // token delle correzioni del digest
const cfg = $('Configurazione').first().json;
const { fatti, body } = $('Fatti per il digest').first().json;
const testi = new Map($('Recensioni pronte').all().map((i) => [i.json.review_id, i.json.title + '\n' + i.json.text]));

const norm = (s) =>
  String(s ?? '')
    .normalize('NFKC')
    .toLowerCase()
    .replace(/[“”„"]/g, '"')
    .replace(/[‘’`´]/g, "'")
    .replace(/…/g, '...')
    .replace(/\s+/g, ' ')
    .trim();
const maiusc = (s) => String(s).replace(/^./, (c) => c.toUpperCase());
const SEZIONI = ['apprezzati', 'criticati', 'segnalate'];
const COMMENTI = ['sintesi', 'commento_apprezzati', 'commento_criticati', 'commento_tempo', 'commento_segnalate'];

function leggi(content) {
  try {
    return JSON.parse(content);
  } catch (e) {
    return null;
  }
}

// >>> CONTROLLO AFFERMAZIONI (inizio)
// Controllo dei commenti contro i fatti. Il modello non scrive numeri, ma puo' scrivere affermazioni
// sbagliate a parole (nel digest dell'hotel: «divisivi» per aspetti che non lo sono, «aumentano le
// critiche» dove i numeri mostrano solo un calo dei giudizi positivi). Per ogni frase dei commenti:
// - se dice «divisivo», ogni aspetto nominato deve essere tra i piu' divisivi;
// - se dice che le critiche (lamentele, giudizi negativi) aumentano, ogni aspetto nominato deve avere
//   un aumento significativo della quota di recensioni che lo criticano;
// - se dice che l'apprezzamento (soddisfazione, giudizi positivi) cala, ogni aspetto nominato deve
//   avere un calo significativo della quota di recensioni che lo apprezzano.
// Gli aspetti si riconoscono dalle parole del loro nome (radici di almeno 4 lettere, senza parole generiche).
function controllaAffermazioni(o, A) {
  const problemi = [];
  if (!o || !A) return problemi;
  // parole che compaiono in quasi ogni commento e non identificano un aspetto (es. «aspetti divisivi» non e' l'aspetto «Design e aspetto»)
  const GENERICHE = new Set(['dell', 'della', 'delle', 'degli', 'dello', 'sulla', 'nella', 'app', 'utenti', 'utente', 'generale', 'altri', 'altre', 'aspetto', 'aspetti', 'recensioni', 'recensione', 'esperienza']);
  const radice = (w) => w.slice(0, Math.min(w.length, 6));
  const parole = (s) => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').split(/[^a-z]+/).filter(Boolean);
  const aspetti = A.aspetti.map((a) => ({ nome: a.nome, chiavi: [...new Set(parole(a.nome).filter((w) => w.length >= 4 && !GENERICHE.has(w)).map(radice))] }));
  const sig = (misura, direzione) => new Set(A.andamento.filter((x) => x.significativo && x.misura === misura && x.direzione === direzione).map((x) => x.nome));
  const critAumento = sig('pct_recensioni_che_lo_criticano', 'aumento');
  const apprCalo = sig('pct_recensioni_che_lo_apprezzano', 'calo');
  const divisivi = new Set((A.classifiche.piu_criticati_per_tasso ?? []).filter((x) => x.pct_negative_su_menzioni >= 30).slice(0, 3).map((x) => x.nome));
  const regole = [
    // «meno divisivo» / «non divisivo» non e' un'affermazione di divisivita'
    { dice: (f) => /divisiv/.test(f) && !/(meno|non|poco) (molto )?divisiv/.test(f), vale: (n) => divisivi.has(n), cosa: "e' tra gli aspetti piu' divisivi" },
    // solo verbi di aumento: «la maggior parte» o «in piu'» non dicono che qualcosa e' aumentato
    { dice: (f) => /(aument|cresc)/.test(f) && /(critic|lament|negativ|insoddisf)/.test(f), vale: (n) => critAumento.has(n), cosa: 'ha un aumento significativo delle critiche' },
    { dice: (f) => /(calo|cala|calat|diminu|scend|ridott|peggior)/.test(f) && /(apprezz|soddisf|positiv|gradiment)/.test(f), vale: (n) => apprCalo.has(n), cosa: "ha un calo significativo dell'apprezzamento" },
  ];
  for (const campo of ['sintesi', 'commento_apprezzati', 'commento_criticati', 'commento_tempo', 'commento_segnalate']) {
    const frasi = String(o[campo] ?? '').split(/(?<=[.!?;])\s+/);
    for (const frase of frasi) {
      const f = frase.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
      const radiciFrase = new Set(parole(frase).map(radice));
      const nominati = aspetti.filter((a) => a.chiavi.length && a.chiavi.some((k) => radiciFrase.has(k))).map((a) => a.nome);
      // «divisivo» si controlla da solo; le affermazioni sul tempo (critiche in aumento, apprezzamento in calo)
      // spesso stanno nella stessa frase e si riferiscono ad aspetti diversi: basta che l'aspetto ne rispetti una
      const [divisivo, ...tempo] = regole;
      if (divisivo.dice(f)) {
        const sbagliati = nominati.filter((n) => !divisivo.vale(n));
        if (sbagliati.length) problemi.push(`nel campo ${campo} la frase «${frase.trim().slice(0, 140)}» dice che ${sbagliati.join(', ')} ${divisivo.cosa}, ma nei fatti non e' cosi': togli quell'aspetto dalla frase o riformula senza quell'affermazione`);
      }
      const dette = tempo.filter((r) => r.dice(f));
      if (dette.length) {
        const sbagliati = nominati.filter((n) => !dette.some((r) => r.vale(n)));
        if (sbagliati.length) problemi.push(`nel campo ${campo} la frase «${frase.trim().slice(0, 140)}» dice che ${sbagliati.join(', ')} ${dette.map((r) => r.cosa).join(' o ')}, ma nei fatti non e' cosi': togli quell'aspetto dalla frase o riformula senza quell'affermazione`);
      }
    }
  }
  return problemi;
}
// <<< CONTROLLO AFFERMAZIONI (fine)

const aggregazioneFatti = $('Aggregazione').first().json.aggregazione;

function controlla(o) {
  if (!o) return ['la risposta non e\' un JSON valido'];
  // una citazione troppo lunga si ACCORCIA da sola alle prime 30 parole con «...» (resta copiata parola per parola):
  // il 17/11 il modello ha scelto tre volte la stessa citazione lunga e tutto il commento e' stato scartato
  for (const c of Array.isArray(o.citazioni) ? o.citazioni : []) {
    const parole = String(c.testo ?? '').trim().split(/\s+/);
    if (parole.length > 30) c.testo = parole.slice(0, 30).join(' ').replace(/[,;:]$/, '') + '...';
  }
  const problemi = [];
  for (const k of COMMENTI) {
    const t = String(o[k] ?? '').trim();
    if (!t) problemi.push(`il campo ${k} e' vuoto`);
    const cifre = t.match(/\d+/g);
    if (cifre) problemi.push(`il campo ${k} contiene cifre (${cifre.slice(0, 5).join(', ')}): descrivi a parole, senza numeri ne' anni`);
    if (/[«»]/.test(t)) problemi.push(`il campo ${k} contiene virgolette « »: le citazioni vanno solo nel campo "citazioni"`);
  }
  const cit = Array.isArray(o.citazioni) ? o.citazioni : [];
  for (const s of SEZIONI) if (!cit.some((c) => c.sezione === s)) problemi.push(`manca una citazione per la sezione "${s}"`);
  for (const c of cit) {
    const testo = testi.get(c.review_id);
    if (!testo) {
      problemi.push(`la citazione per "${c.sezione}" indica un identificativo inesistente (${c.review_id})`);
      continue;
    }
    const pezzi = norm(c.testo).split(/\.{3,}/).map((p) => p.trim().replace(/^["'.,;:\s]+|["',;:\s]+$/g, '')).filter((p) => p.length > 2);
    if (!pezzi.length || !pezzi.every((p) => norm(testo).includes(p))) {
      problemi.push(`la citazione «${String(c.testo).slice(0, 60)}...» non e' copiata parola per parola dalla recensione ${c.review_id}: copia frasi consecutive senza cambiare parole, oppure segna con "..." le parti saltate`);
    }
    if (String(c.testo).split(/\s+/).length > 40) problemi.push(`la citazione della recensione ${c.review_id} supera 30 parole`);
    // un frammento troppo corto non dice niente a chi legge
    // ...ma se la recensione intera e' corta, la citazione puo' essere tutta la recensione
    const paroleCit = String(c.testo).replace(/\.{3,}/g, ' ').trim().split(/\s+/).length;
    const paroleRec = String(testo).trim().split(/\s+/).length;
    if (paroleCit < 6 && paroleRec > paroleCit + 2) problemi.push(`la citazione della recensione ${c.review_id} e' troppo corta: scegli una frase di almeno 8 parole che si capisca da sola`);
    const numeriCitazione = new Set(String(c.testo).match(/\d+/g) ?? []);
    for (const n of String(c.traduzione ?? '').match(/\d+/g) ?? []) {
      if (!numeriCitazione.has(n)) problemi.push(`la traduzione della citazione ${c.review_id} contiene il numero ${n}, che non e' nella citazione`);
    }
  }
  problemi.push(...controllaAffermazioni(o, aggregazioneFatti));
  // niente frasi sulle lingue se non c'e' stato un confronto tra lingue (recensioni quasi tutte in una lingua)
  if (!fatti.lingue_confrontate) {
    for (const k of COMMENTI) if (/lingu/i.test(String(o[k] ?? ''))) problemi.push(`il campo ${k} parla di lingue, ma le recensioni sono quasi tutte in una sola lingua e non c'e' stato nessun confronto: togli la frase sulle lingue`);
  }
  return problemi;
}

// --- citazioni per la versione di riserva: una frase della recensione che contiene una parola dell'aspetto
function fraseSullAspetto(testo, paroleChiave) {
  // frasi di almeno 8 parole: un frammento corto non si capisce da solo (17/11)
  const frasi = testo.split(/(?<=[.!?])\s+|\n+/).map((s) => s.trim()).filter((s) => s.split(/\s+/).length >= 8);
  const scelta = frasi.find((s) => paroleChiave.some((k) => s.toLowerCase().includes(k))) ?? frasi[0] ?? testo;
  const parole = scelta.split(/\s+/);
  return parole.length > 30 ? parole.slice(0, 30).join(' ').replace(/[,;:]$/, '') + '...' : scelta;
}
function citazioniDiRiserva(sezione) {
  const giaCitate = new Set();
  return fatti.citazioni_disponibili
    .filter((c) => c.per.startsWith(sezione === 'apprezzati' ? 'apprezzato' : 'criticato'))
    .slice(0, 2)
    .map((c) => {
      const r = c.recensioni.find((x) => !giaCitate.has(x.review_id));
      if (!r) return null;
      giaCitate.add(r.review_id);
      return { sezione, review_id: r.review_id, testo: fraseSullAspetto(r.testo, c.parole_chiave ?? []), traduzione: '' };
    })
    .filter(Boolean);
}

// accenti veri al posto dell'apostrofo («e'» -> «è», «perche'» -> «perché»), solo FUORI dalle citazioni «...»,
// che restano copiate parola per parola (17/11: nello stesso testo c'erano «e'» del codice e «è» del modello)
const ACUTE = new Set(['perche', 'poiche', 'affinche', 'benche', 'finche', 'giacche', 'nonche', 'sicche', 'ne']);
const GRAVE = { a: 'à', e: 'è', i: 'ì', o: 'ò', u: 'ù', A: 'À', E: 'È', I: 'Ì', O: 'Ò', U: 'Ù' };
const accentaPezzo = (s) => s.replace(/(^|[^A-Za-zÀ-ÿ'])([A-Za-zÀ-ÿ]*?)([aeiouAEIOU])'(?=[\s.,;:!?)\]]|$)/g, (m, prima, radice, v) => {
  const parola = (radice + v).toLowerCase();
  if (parola === 'po') return m;
  return prima + radice + (ACUTE.has(parola) && v.toLowerCase() === 'e' ? (v === 'E' ? 'É' : 'é') : GRAVE[v]);
});
const conAccenti = (testo) => String(testo).split(/(«[^»]*»)/).map((p) => (p.startsWith('«') ? p : accentaPezzo(p))).join('');

// --- composizione del digest
function componi(o) {
  const f = fatti;
  const r = [];
  const citazioni = (sezione) => {
    const lista = o ? (o.citazioni ?? []).filter((c) => c.sezione === sezione) : sezione === 'segnalate' ? [] : citazioniDiRiserva(sezione);
    return lista.flatMap((c) => [`> «${c.testo}» (${c.review_id})${c.traduzione ? ` [${c.traduzione}]` : ''}`, '']);
  };
  r.push('# Digest delle recensioni', '');

  r.push('## In sintesi', '', f.frase_sintesi, '');
  if ((f.frasi_piattaforme ?? []).length) { r.push('Per piattaforma (iOS e Android non si confrontano tra loro):', ''); for (const x of f.frasi_piattaforme) r.push(`- ${x}.`); r.push(''); }
  // lingue: una frase sola (17/11: prima una riga per lingua, ripetitive, e anche la lingua «und»)
  if (f.frase_lingue) r.push(f.frase_lingue, '');
  if (o) r.push(o.sintesi.trim(), '');

  r.push("## Cosa apprezzano di piu'", '');
  for (const x of f.aspetti_piu_apprezzati) r.push(`- **${x.aspetto}**: ${x.frase_numeri}.`);
  r.push('');
  if (o) r.push(o.commento_apprezzati.trim(), '');
  r.push(...citazioni('apprezzati'));

  r.push("## Cosa criticano di piu'", '');
  for (const x of f.aspetti_piu_criticati) r.push(`- **${x.aspetto}**: ${x.frase_numeri}.`);
  r.push('');
  if (f.aspetti_piu_divisivi.length) {
    r.push("Gli aspetti piu' divisivi, cioe' con pareri spaccati tra chi ne parla (tra il 30% e il 70% di giudizi negativi):", '');
    for (const x of f.aspetti_piu_divisivi) r.push(`- **${x.aspetto}**: ${x.frase_numeri}.`);
    r.push('');
  }
  if (o) r.push(o.commento_criticati.trim(), '');
  r.push(...citazioni('criticati'));

  r.push('## Come cambiano le cose nel tempo', '');
  r.push(`Le recensioni sono raggruppate in periodi con abbastanza recensioni per un confronto. Italiano e inglese sono confrontati separatamente, perche' la quota di recensioni in inglese cambia nel tempo. Sono stati fatti ${f.confronti_nel_tempo_eseguiti} confronti tra l'ultimo periodo e i precedenti: ${f.confronti_nel_tempo_significativi} risultano significativi dopo la correzione per confronti multipli.`, '');
  for (const x of f.cambiamenti_significativi) r.push(`- ${x.frase_numeri}.`);
  if (f.cambiamenti_significativi.length) r.push('');
  // versioni: solo le ultime con abbastanza recensioni (prima erano decine di righe); tutte nel foglio Versioni
  const NOME_PF = { ios: 'iOS', android: 'Android' };
  for (const p of f.per_piattaforma ?? []) {
    r.push(`Versioni dell'app su ${NOME_PF[p.piattaforma] ?? p.piattaforma} (le ultime con abbastanza recensioni per le statistiche):`, '');
    for (const v of p.versioni) {
      r.push(v.nota ? `- versione ${v.versione}: ${v.recensioni} recensioni, ${v.nota}.` : `- versione ${v.versione}: ${v.recensioni} recensioni, voto medio ${v.voto_medio}, positive ${v.positive}, negative ${v.negative}.`);
    }
    if (p.versioni_non_mostrate && p.versioni_non_mostrate !== '0') r.push(`- altre ${p.versioni_non_mostrate} versioni (piu' vecchie o con poche recensioni): nel foglio Versioni dell'Excel.`);
    for (const x of p.cambiamenti_ultima_versione) r.push(`- ${x.aspetto}${x.lingua ? ` (recensioni in ${x.lingua})` : ''}: ${x.misura} in ${x.direzione}, ${x.valore_ultima_versione} nella versione ${x.ultima_versione} contro ${x.valore_di_confronto} nella ${String(x.confrontata_con).replace(/^la /, '')}.`);
    r.push('');
  }
  if (o) r.push(o.commento_tempo.trim(), '');
  // periodi: gli ultimi 12 (prima erano decine di righe); tutti nei fogli Mesi e Due settimane dell'Excel
  const ULTIMI_PERIODI = 12;
  r.push(f.periodi.length > ULTIMI_PERIODI ? `Andamento per periodo (gli ultimi ${ULTIMI_PERIODI}; quelli prima sono nell'Excel, fogli Mesi e Due settimane):` : 'Andamento per periodo:', '');
  for (const p of f.periodi.slice(-ULTIMI_PERIODI)) r.push(`- ${maiusc(p.frase_numeri)}.`);
  r.push('');

  r.push('## Recensioni da guardare', '');
  if (f.frase_segnalate_recenti) r.push(f.frase_segnalate_recenti, '');
  r.push(f.frase_segnalate, '');
  if (f.frase_campagne) r.push(f.frase_campagne, '');
  for (const s of f.segnalate_da_mostrare) r.push(`- ${s.review_id} (${s.data}${s.voto ? `, voto ${s.voto}` : ''}, priorita' ${s.priorita}): ${String(s.motivo ?? '').replace(/\.\s*;/g, ';')}`);
  r.push('');
  if (o) r.push(o.commento_segnalate.trim(), '');
  r.push(...citazioni('segnalate'));

  r.push('## Come sono stati ottenuti questi numeri', '');
  r.push("Ogni recensione e' stata letta da un modello linguistico, nella sua lingua, che ne ha indicato il giudizio complessivo e il giudizio sugli aspetti di un elenco fisso. Tutti i numeri di questo testo sono conteggi calcolati dal sistema su quelle analisi; i cambiamenti nel tempo sono indicati solo quando superano la soglia statistica dopo la correzione per confronti multipli. Le segnalazioni seguono criteri fissati in anticipo e ognuna ha una frase di prova presa dalla recensione.");
  r.push('');
  r.push(o
    ? "I commenti a parole e la scelta delle citazioni sono del modello; ogni citazione e' stata controllata parola per parola sulla recensione originale."
    : "Questa versione non contiene i commenti del modello, perche' non hanno superato i controlli automatici; le citazioni sono scelte dal sistema.");
  // le righe delle citazioni («> ...») restano come sono; nelle altre accenti veri (fuori dalle «»)
  return r.map((riga) => (riga.startsWith('>') ? riga : conAccenti(riga))).join('\n');
}

// --- chiamata al modello con le correzioni
async function chiedi(messaggi) {
  const res = await helpers.httpRequest({
    method: 'POST',
    url: cfg.base_url + '/chat/completions',
    headers: { Authorization: 'Bearer ' + $env.OPENAI_API_KEY },
    body: { ...body, messages: messaggi },
    json: true,
    timeout: 180000,
  });
  if (res.usage) usoToken.push(res.usage);
  return String(res.choices?.[0]?.message?.content ?? '');
}

let risposta = String($input.first().json?.choices?.[0]?.message?.content ?? '');
let o = leggi(risposta);
let problemi = controlla(o);
const tentativi = [{ tentativo: 1, ok: problemi.length === 0, problemi }];
let messaggi = [...body.messages];
for (let t = 2; t <= 3 && problemi.length; t++) {
  messaggi = [
    ...messaggi,
    { role: 'assistant', content: risposta || '(vuoto)' },
    { role: 'user', content: 'La risposta non supera i controlli automatici. Correggi questi problemi e restituisci di nuovo il JSON completo:\n- ' + problemi.join('\n- ') },
  ];
  try {
    risposta = await chiedi(messaggi);
    o = leggi(risposta);
    problemi = controlla(o);
  } catch (e) {
    problemi = ['errore di chiamata al modello: ' + e.message];
  }
  tentativi.push({ tentativo: t, ok: problemi.length === 0, problemi });
}

const usaModello = problemi.length === 0;
const riserva = componi(null);
return [{
  json: {
    digest: usaModello ? componi(o) : riserva,
    origine: usaModello ? 'modello' : 'riserva_controlli_non_superati',
    verifica: { tentativi, esito_finale: { ok: usaModello, problemi } },
    uso_token: usoToken,
    digest_riserva: riserva,
    esito_riserva: { ok: true, nota: 'composto dal codice: numeri dalle frasi dei fatti, citazioni scelte dal sistema' },
    // risposta del modello scartata, conservata per capire perche'
    ultimo_testo_modello: usaModello ? null : risposta,
  },
}];

// USA IL DIGEST DI RISERVA
// Si arriva qui solo se il guardrail di uscita ha trovato nel digest dati
// personali, link, chiavi o nomi di persone. Il testo non viene pubblicato:
// si usa il digest di riserva, scritto senza modello dagli stessi fatti.
const v = $('Verifica digest').first().json;
const controlli = ($input.first().json.checks ?? []).filter((c) => c.triggered);
return [{
  json: {
    digest: v.digest_riserva,
    origine: 'riserva_guardrail_uscita',
    guardrail_uscita: controlli.map((c) => ({ controllo: c.name, info: c.info ?? null, confidenza: c.confidenceScore ?? null })),
  },
}];

// PREPARA I FILE DI OUTPUT
// Ultimo controllo dello schema di ogni recensione, poi scrive:
//   recensioni_analizzate.json   un oggetto per recensione, nello schema richiesto
//   recensioni_analizzate.jsonl  lo stesso, una riga per recensione
//   aspetti.json                 elenco finale degli aspetti con descrizione
//   aggregazione.json            conteggi, classifiche, periodi, andamento
//   digest.md                    testo per la direzione
//   esecuzione.json              diagnostica: guardrail, ritentativi, scarti, verifiche
//   recensioni_diagnostica.jsonl dettaglio per recensione (segnalazioni con prova, temi fuori elenco)
const cfg = $('Configurazione').first().json;
const tax = $('Valida tassonomia').first().json;
// con l'elenco fisso la scoperta non gira: questi nodi possono non avere dati
let temi = { temi: [] };
let campione = [];
try {
  temi = $('Raccogli temi').first().json;
  campione = $('Campione per scoperta aspetti').all().flatMap((i) => i.json.ids);
} catch (e) {
  // elenco fisso
}
const pronte = $('Recensioni pronte').all().map((i) => i.json);
const analisi = $('Valida e completa').all().map((i) => i.json);
const { aggregazione, info_analisi } = $('Aggregazione').first().json;
const verifica = $('Verifica digest').first().json;
const aggiornamento = $('Aggiorna elenco degli aspetti').first().json;

// il digest arriva o dal ramo "passa" del guardrail di uscita o dal digest di riserva
const ingresso = $input.first().json;
const digestFinale = ingresso.guardrailsInput !== undefined
  ? { digest: verifica.digest, origine: verifica.origine, guardrail_uscita: 'superato' }
  : { digest: ingresso.digest, origine: ingresso.origine, guardrail_uscita: ingresso.guardrail_uscita };

// --- schema fisso, controllato prima di scrivere
const OVERALL = ['positive', 'negative', 'mixed', 'neutral'];
const SENT = ['positive', 'negative', 'neutral'];
const idAspetti = new Set(tax.aspetti.map((a) => a.aspect));
const recensioni = analisi.map((r) => ({
  review_id: r.review_id,
  language: r.language,
  overall_sentiment: r.overall_sentiment,
  aspects: r.aspects.map((a) => ({ aspect: a.aspect, sentiment: a.sentiment })),
  needs_attention: r.needs_attention === true,
  attention_reason: r.needs_attention ? r.attention_reason : null,
}));
const errori = [];
const ids = new Set();
for (const r of recensioni) {
  if (typeof r.review_id !== 'string' || ids.has(r.review_id)) errori.push(`review_id non valido o ripetuto: ${r.review_id}`);
  ids.add(r.review_id);
  if (typeof r.language !== 'string' || !r.language) errori.push(`${r.review_id}: language mancante`);
  if (!OVERALL.includes(r.overall_sentiment)) errori.push(`${r.review_id}: overall_sentiment non ammesso`);
  for (const a of r.aspects) if (!idAspetti.has(a.aspect) || !SENT.includes(a.sentiment)) errori.push(`${r.review_id}: aspetto non valido ${JSON.stringify(a)}`);
  if (r.needs_attention && (typeof r.attention_reason !== 'string' || !r.attention_reason)) errori.push(`${r.review_id}: motivo mancante`);
}
if (recensioni.length !== pronte.length) errori.push(`recensioni in output ${recensioni.length} invece di ${pronte.length}`);
if (errori.length) throw new Error('Output non conforme allo schema:\n' + errori.slice(0, 20).join('\n'));

const aspetti = tax.aspetti.map((a) => ({ aspect: a.aspect, nome: a.nome, descrizione: a.descrizione, temi_raggruppati: a.temi_raggruppati }));

// temi giudicati che non rientrano in nessun aspetto: misura di quanto l'elenco copre
const nonMappati = {};
for (const r of analisi) for (const u of r.unmapped ?? []) nonMappati[u] = (nonMappati[u] ?? 0) + 1;
const conNonMappati = analisi.filter((r) => (r.unmapped ?? []).length > 0).length;

const oscurati = {};
for (const r of pronte) for (const [k, v] of Object.entries(r.dati_oscurati ?? {})) oscurati[k] = (oscurati[k] ?? 0) + v;

const esecuzione = {
  // l'indirizzo dei report di Google resta solo nel .env: qui si dice soltanto se c'e'
  configurazione: { ...cfg, input_file: cfg.input_file, play_bucket: cfg.play_bucket ? '(impostato)' : '' },
  terminata_il: new Date().toISOString(),
  file: aggregazione.meta.righe_nel_file + ' righe lette da ' + cfg.input_file,
  anomalie_del_file: pronte[0]._file.anomalie,
  guardrail_ingresso: {
    dati_oscurati_prima_del_modello: oscurati,
    recensioni_con_dati_oscurati: pronte.filter((r) => Object.keys(r.dati_oscurati ?? {}).length).map((r) => r.review_id),
    recensioni_sospette_di_manipolazione: pronte.filter((r) => r.sospetta).map((r) => ({ review_id: r.review_id, controlli: r.guardrail_scattati })),
    errori_del_guardrail: pronte.filter((r) => r.guardrail_errore).map((r) => ({ review_id: r.review_id, errore: r.guardrail_errore })),
  },
  scoperta_aspetti: {
    origine: tax.origine_aspetti,
    versione: tax.versione_aspetti,
    recensioni_nel_campione: campione.length,
    campione: campione,
    temi_liberi_distinti: temi.temi.length,
    temi_piu_frequenti: temi.temi.slice(0, 40),
    copertura_temi_pct: tax.copertura_temi_pct,
    soglia_temi_frequenti: tax.soglia_temi_frequenti,
    giri_di_consolidamento: tax.giri_consolidamento,
    temi_tolti_perche_doppi: tax.temi_tolti_perche_doppi,
    temi_non_coperti: tax.temi_non_coperti,
  },
  analisi: {
    ...info_analisi,
    recensioni_con_temi_fuori_elenco: conNonMappati,
    temi_fuori_elenco_piu_frequenti: Object.entries(nonMappati).sort((a, b) => b[1] - a[1]).slice(0, 30).map(([tema, n]) => ({ tema, recensioni: n })),
  },
  digest: {
    origine: digestFinale.origine,
    guardrail_uscita: digestFinale.guardrail_uscita,
    verifica: verifica.verifica,
    testo_del_modello_scartato: verifica.ultimo_testo_modello,
  },
  fatti_dati_al_modello_per_il_digest: $('Fatti per il digest').first().json.fatti,
};

// --- tabelle CSV per strumenti di visualizzazione (Tableau, Excel, Power BI)
const campoCsv = (v) => {
  const s = v === null || v === undefined ? '' : String(v);
  return /[",\n\r;]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
};
const tabellaCsv = (colonne, righe) => [colonne.join(','), ...righe.map((r) => colonne.map((c) => campoCsv(r[c])).join(','))].join('\n') + '\n';
const nomeAspetto = Object.fromEntries(tax.aspetti.map((a) => [a.aspect, a.nome]));
// una riga per ogni coppia recensione-aspetto (le recensioni senza aspetti hanno una riga con aspetto vuoto)
const righeRecensioni = [];
for (const r of analisi) {
  const base = {
    review_id: r.review_id,
    data_pubblicazione: r.published_date ?? '',
    anno: r.anno ?? '',
    mese: r.published_date ? r.published_date.slice(0, 7) : '',
    voto: r.rating ?? '',
    lingua: r.language,
    piattaforma: r.piattaforma ?? '',
    versione: r.versione ?? '',
    sentiment_complessivo: r.overall_sentiment,
    da_segnalare: r.needs_attention,
    priorita: r.priorita ?? '',
    nei_conteggi: (r.stato === 'ok' || r.stato === 'ritentata') && !r.sospetta,
  };
  if (!r.aspects.length) righeRecensioni.push({ ...base, aspetto: '', nome_aspetto: '', sentiment_aspetto: '' });
  for (const a of r.aspects) righeRecensioni.push({ ...base, aspetto: a.aspect, nome_aspetto: nomeAspetto[a.aspect] ?? a.aspect, sentiment_aspetto: a.sentiment });
}
// una riga per ogni coppia periodo-aspetto, con i conteggi dell'aggregazione
const righePeriodi = aggregazione.periodi.flatMap((p) => Object.values(p.aspetti).map((a) => ({
  periodo: p.periodo,
  recensioni_del_periodo: p.recensioni,
  aspetto: a.aspect,
  nome_aspetto: a.nome,
  menzioni: a.menzioni,
  positive: a.positive,
  negative: a.negative,
  neutral: a.neutral,
  pct_recensioni_che_lo_apprezzano: a.pct_recensioni_che_lo_apprezzano,
  pct_recensioni_che_lo_criticano: a.pct_recensioni_che_lo_criticano,
})));

// --- registro del giro: token, costo e durata
// Token ESATTI per le chiamate fatte dal workflow (nodi HTTP e ritentativi nei nodi Code).
// Il guardrail con il modello lo esegue n8n al suo interno e non espone i token:
// per quello c'e' una STIMA dalla lunghezza dei testi (circa 4 caratteri per token).
const somma = (lista) => lista.reduce((t, u) => ({
  chiamate: t.chiamate + 1,
  token_input: t.token_input + (u?.prompt_tokens ?? 0),
  token_output: t.token_output + (u?.completion_tokens ?? 0),
}), { chiamate: 0, token_input: 0, token_output: 0 });
const usoDelNodo = (nomeNodo) => {
  try {
    return $(nomeNodo).all().map((i) => i.json?.usage).filter(Boolean);
  } catch (e) {
    return []; // nodo non eseguito (per esempio la scoperta con l'elenco fisso)
  }
};
const costo = (v) => Math.round(1e4 * ((v.token_input * cfg.prezzo_input_usd_per_milione + v.token_output * cfg.prezzo_output_usd_per_milione) / 1e6)) / 1e4;
const voci = {
  scoperta_temi_liberi: somma(usoDelNodo('LLM: temi liberi')),
  consolidamento_aspetti: somma([...usoDelNodo('LLM: consolida aspetti'), ...(tax.uso_token ?? [])]),
  analisi_recensioni: somma([...usoDelNodo('LLM: analisi recensioni'), ...(info_analisi.uso_token_ritentativi ?? [])]),
  digest: somma([...usoDelNodo('LLM: scrive digest'), ...(verifica.uso_token ?? [])]),
  aggiornamento_elenco: somma(aggiornamento.aggiornamento_elenco?.uso_token ?? []),
};
for (const v of Object.values(voci)) v.costo_usd = costo(v);
// stima per il guardrail con il modello: una chiamata per ogni recensione non gia' fermata dalle espressioni regolari
// (solo le recensioni controllate in questo giro: le altre hanno l'esito dalla memoria del guardrail)
const nelGuardrail = pronte.filter((r) => !r.guardrail_dalla_memoria && !(r.guardrail_scattati ?? []).some((c) => c !== 'jailbreak'));
const stimaGuardrail = {
  chiamate: nelGuardrail.length + 1,
  token_input: Math.round(nelGuardrail.reduce((t, r) => t + (1300 + r.title.length + r.text.length) / 4, 0) + (1300 + digestFinale.digest.length) / 4),
  token_output: (nelGuardrail.length + 1) * 30,
  nota: 'STIMA: token calcolati dalla lunghezza dei testi, n8n non li espone per i nodi Guardrails',
};
stimaGuardrail.costo_usd = costo(stimaGuardrail);
const misurato = Object.values(voci).reduce((t, v) => ({ token_input: t.token_input + v.token_input, token_output: t.token_output + v.token_output, costo_usd: t.costo_usd + v.costo_usd }), { token_input: 0, token_output: 0, costo_usd: 0 });
const fine = new Date();
const analisiMemoria = $('Valida e completa').first().json._memoria ?? null;
// memoria del guardrail «manipolazione»: esito di ogni recensione con la sua firma (gli errori tecnici no)
const guardrailMemoria = {
  versione_formato: 1,
  aggiornata_il: new Date().toISOString(),
  voci: Object.fromEntries(pronte.filter((r) => r.guardrail_firma && !r.guardrail_errore)
    .map((r) => [r.review_id, { firma: r.guardrail_firma, sospetta: !!r.sospetta, scattati: r.guardrail_scattati ?? [] }])),
};
const registroGiro = {
  inizio: cfg.started_at,
  fine: fine.toISOString(),
  durata_minuti: Math.round((fine - new Date(cfg.started_at)) / 6000) / 10,
  modello: cfg.model,
  prezzi_usd_per_milione_di_token: { input: cfg.prezzo_input_usd_per_milione, output: cfg.prezzo_output_usd_per_milione },
  recensioni: analisi.length,
  versione_aspetti: tax.versione_aspetti,
  // memoria delle analisi: quante recensioni sono state riprese dal giro prima e quante mandate al modello
  analisi_riprese_dalla_memoria: info_analisi.dalla_memoria ?? 0,
  analisi_mandate_al_modello: info_analisi.analizzate_in_questo_giro ?? null,
  guardrail_ripresi_dalla_memoria: pronte.filter((r) => r.guardrail_dalla_memoria).length,
  guardrail_controllati_in_questo_giro: pronte.filter((r) => !r.guardrail_dalla_memoria).length,
  misurato_per_fase: voci,
  misurato_totale: { ...misurato, costo_usd: Math.round(1e4 * misurato.costo_usd) / 1e4 },
  guardrail_stimato: stimaGuardrail,
  costo_totale_usd_misurato_piu_stimato: Math.round(1e4 * (misurato.costo_usd + stimaGuardrail.costo_usd)) / 1e4,
  costo_per_1000_recensioni_usd: Math.round(1e4 * ((misurato.costo_usd + stimaGuardrail.costo_usd) / analisi.length) * 1000) / 1e4,
};
esecuzione.registro_giro = registroGiro;
const { uso_token: _ignora, ...rapportoAggiornamento } = aggiornamento.aggiornamento_elenco ?? {};
esecuzione.aggiornamento_elenco = rapportoAggiornamento;

// --- elenco fisso: nuova versione adottata e/o linea di base misurata in questo giro
const fileElenco = [];
let elencoInUso = null;
try {
  elencoInUso = $('Estrai elenco fisso').first().json.data ?? null;
} catch (e) {
  elencoInUso = null;
}
if (elencoInUso && Array.isArray(elencoInUso.aspetti)) {
  const dirElenco = cfg.aspects_file.replace(/\/[^/]+$/, '');
  const inUso = aggiornamento.linea_di_base_misurata ? { ...elencoInUso, linea_di_base_temi_fuori_elenco: aggiornamento.linea_di_base_misurata } : elencoInUso;
  if (aggiornamento.nuovo_elenco) {
    // la versione in uso va in archivio, la nuova prende il suo posto
    fileElenco.push({ path: `${dirElenco}/aspetti_${inUso.versione}.json`, contenuto: inUso });
    fileElenco.push({ path: cfg.aspects_file, contenuto: aggiornamento.nuovo_elenco });
  } else if (aggiornamento.linea_di_base_misurata) {
    fileElenco.push({ path: cfg.aspects_file, contenuto: inUso });
  }
}

const dir = cfg.output_dir;
const file = (nome, contenuto, mime) => ({
  json: { path: `${dir}/${nome}` },
  binary: { data: { data: Buffer.from(contenuto, 'utf8').toString('base64'), mimeType: mime, fileName: nome } },
});
let digest = digestFinale.digest;
if (!/^#\s/m.test(digest)) digest = '# Digest delle recensioni\n\n' + digest;

return [
  file('recensioni_analizzate.json', JSON.stringify(recensioni, null, 2), 'application/json'),
  file('recensioni_analizzate.jsonl', recensioni.map((r) => JSON.stringify(r)).join('\n') + '\n', 'application/x-ndjson'),
  file('aspetti.json', JSON.stringify({ versione: tax.versione_aspetti, origine: tax.origine_aspetti, aspetti }, null, 2), 'application/json'),
  file('aggregazione.json', JSON.stringify(aggregazione, null, 2), 'application/json'),
  file('digest.md', digest + '\n', 'text/markdown'),
  file('tabella_recensioni_aspetti.csv', tabellaCsv(['review_id', 'data_pubblicazione', 'anno', 'mese', 'voto', 'lingua', 'piattaforma', 'versione', 'sentiment_complessivo', 'da_segnalare', 'priorita', 'nei_conteggi', 'aspetto', 'nome_aspetto', 'sentiment_aspetto'], righeRecensioni), 'text/csv'),
  file('tabella_aspetti_per_periodo.csv', tabellaCsv(['periodo', 'recensioni_del_periodo', 'aspetto', 'nome_aspetto', 'menzioni', 'positive', 'negative', 'neutral', 'pct_recensioni_che_lo_apprezzano', 'pct_recensioni_che_lo_criticano'], righePeriodi), 'text/csv'),
  file('esecuzione.json', JSON.stringify(esecuzione, null, 2), 'application/json'),
  file('registro_giro.json', JSON.stringify(registroGiro, null, 2), 'application/json'),
  // memoria delle analisi per il giro dopo (vedi «Prepara richieste analisi»)
  ...(analisiMemoria ? [file('memoria_analisi.json', JSON.stringify(analisiMemoria), 'application/json')] : []),
  file('memoria_guardrail.json', JSON.stringify(guardrailMemoria), 'application/json'),
  ...fileElenco.map((f) => ({
    json: { path: f.path },
    binary: { data: { data: Buffer.from(JSON.stringify(f.contenuto, null, 2), 'utf8').toString('base64'), mimeType: 'application/json', fileName: f.path.split('/').pop() } },
  })),
  // dettaglio per recensione, fuori dallo schema richiesto: serve a controllare e a verificare
  file('recensioni_diagnostica.jsonl', analisi.map((r, i) => JSON.stringify({
    review_id: r.review_id,
    stato: r.stato,
    sospetta: r.sospetta,
    guardrail_scattati: pronte[i].guardrail_scattati,
    dati_oscurati: pronte[i].dati_oscurati,
    priorita: r.priorita,
    segnalazioni: r.segnalazioni,
    temi_fuori_elenco: r.unmapped,
  })).join('\n') + '\n', 'application/x-ndjson'),
];

// VOTO NEGLI STORE PER MERCATO
// Il voto che si vede negli store NON e' la media delle recensioni scritte: conta anche chi da' solo le stelle.
// Qui si legge il voto vero degli store, per i paesi di VOTO_PAESI (predefiniti Italia, Regno Unito, Stati Uniti),
// e lo si confronta con quello di una settimana prima.
// - iOS: servizio pubblico di Apple (itunes.apple.com/lookup), che da' SOLO il voto di oggi e il numero delle
//   valutazioni. Lo storico lo costruisce il programma: ogni giro salva un'istantanea in storico_voti.json. Dal
//   numero delle valutazioni si ricava anche quanti voti sono arrivati nella settimana e la loro media:
//   (voto oggi x valutazioni oggi - voto prima x valutazioni prima) / (valutazioni oggi - valutazioni prima).
// - Android: report giornalieri della Play Console (stats/ratings/..._country.csv nello stesso spazio dei report
//   delle recensioni), con il voto totale e quello del giorno per paese, dal 2019. Google NON da' il numero delle
//   valutazioni: si vede l'andamento ma non si puo' dire se una differenza e' oltre il rumore. I report arrivano
//   con qualche giorno di ritardo: si scrive fino a che giorno arrivano i dati.
// Se una fonte non risponde il giro continua e lo scrive. Nessun numero viene inventato o stimato.
const crypto = require('crypto');
const cfg = $('Configurazione').first().json;
const helpers = this.helpers;
const NOMI = { it: 'Italia', gb: 'Regno Unito', us: 'Stati Uniti', es: 'Spagna', fr: 'Francia', de: 'Germania', ch: 'Svizzera' };
const paesi = cfg.voto_paesi;
const oggi = cfg.grappolo_oggi ?? new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Rome' });
const giorno = (d) => Math.round(Date.parse(String(d).slice(0, 10) + 'T00:00:00Z') / 86400000);
const comeData = (n) => new Date(n * 86400000).toISOString().slice(0, 10);
const r2 = (x) => (x === null || x === undefined || Number.isNaN(x) ? null : Math.round(100 * x) / 100);

let storico = { istantanee_ios: [] };
try {
  const d = $('Estrai storico voti').first().json.data;
  if (d && Array.isArray(d.istantanee_ios)) storico = d;
} catch (e) {
  // primo giro: nessuno storico
}

// --- iOS: voto di oggi per paese, confronto con l'istantanea di circa una settimana prima
const ios = { fonte: 'App Store (itunes.apple.com/lookup)', stato: 'ok', paesi: [] };
if (!cfg.app_store_id) ios.stato = 'non configurato: manca APP_STORE_ID';
else {
  for (const p of paesi) {
    try {
      let d = await helpers.httpRequest({ method: 'GET', url: `https://itunes.apple.com/lookup?id=${encodeURIComponent(cfg.app_store_id)}&country=${p}`, json: true, timeout: 30000 });
      if (typeof d === 'string') d = JSON.parse(d);
      const a = d?.results?.[0];
      if (!a || typeof a.averageUserRating !== 'number') { ios.paesi.push({ paese: p, nome: NOMI[p] ?? p, stato: 'app non trovata in questo paese' }); continue; }
      const voto = a.averageUserRating, valutazioni = a.userRatingCount ?? null;
      // istantanea di oggi (una per giorno e paese: se il giro si ripete lo stesso giorno, si sostituisce)
      storico.istantanee_ios = storico.istantanee_ios.filter((x) => !(x.data === oggi && x.paese === p));
      storico.istantanee_ios.push({ data: oggi, paese: p, voto, valutazioni, versione: a.version ?? null });
      // confronto: l'istantanea piu' recente di almeno 6 giorni prima
      const prima = storico.istantanee_ios.filter((x) => x.paese === p && giorno(oggi) - giorno(x.data) >= 6)
        .sort((x, y) => y.data.localeCompare(x.data))[0] ?? null;
      const riga = { paese: p, nome: NOMI[p] ?? p, stato: 'ok', voto: r2(voto), valutazioni, versione: a.version ?? null };
      if (prima) {
        riga.voto_prima = r2(prima.voto);
        riga.valutazioni_prima = prima.valutazioni;
        riga.data_prima = prima.data;
        const nuove = valutazioni !== null && prima.valutazioni !== null ? valutazioni - prima.valutazioni : null;
        riga.voti_nuovi = nuove;
        const media = nuove > 0 ? (voto * valutazioni - prima.voto * prima.valutazioni) / nuove : null;
        // controllo di coerenza: le stelle vanno da 1 a 5 (con un piccolo margine per gli arrotondamenti di Apple).
        // Fuori da qui i dati di Apple non sono coerenti tra loro (voto e numero aggiornati in momenti diversi,
        // valutazioni azzerate con una versione nuova): si dice «non calcolabile», non si scrive un numero sbagliato.
        if (media !== null && media >= 0.95 && media <= 5.05) riga.media_voti_nuovi = r2(Math.min(5, Math.max(1, media)));
        else if (nuove !== null) riga.media_voti_nuovi_nota = nuove <= 0 ? 'nessun voto nuovo (o valutazioni azzerate da Apple)' : 'non calcolabile: dati di Apple non coerenti';
      }
      ios.paesi.push(riga);
    } catch (e) {
      ios.paesi.push({ paese: p, nome: NOMI[p] ?? p, stato: 'non raggiungibile: ' + e.message });
    }
  }
}

// --- Android: report giornalieri della Play Console per paese
const android = { fonte: 'Play Console, report delle valutazioni per paese', stato: 'ok', paesi: [], serie_settimanale: [] };
if (!cfg.play_bucket || !cfg.play_package || !$env.GOOGLE_PLAY_CREDENZIALI_B64) android.stato = 'non configurato: servono GOOGLE_PLAY_BUCKET, GOOGLE_PLAY_PACKAGE e GOOGLE_PLAY_CREDENZIALI_B64';
else {
  try {
    const account = JSON.parse(Buffer.from($env.GOOGLE_PLAY_CREDENZIALI_B64, 'base64').toString('utf8'));
    const b64url = (x) => Buffer.from(typeof x === 'string' ? x : JSON.stringify(x)).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
    const ora = Math.floor(Date.now() / 1000);
    const testa = b64url({ alg: 'RS256', typ: 'JWT' });
    const corpo = b64url({ iss: account.client_email, scope: 'https://www.googleapis.com/auth/devstorage.read_only', aud: 'https://oauth2.googleapis.com/token', iat: ora, exp: ora + 3600 });
    const firma = crypto.createSign('RSA-SHA256').update(`${testa}.${corpo}`).sign(account.private_key, 'base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
    let t = await helpers.httpRequest({ method: 'POST', url: 'https://oauth2.googleapis.com/token', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: `grant_type=${encodeURIComponent('urn:ietf:params:oauth:grant-type:jwt-bearer')}&assertion=${testa}.${corpo}.${firma}`, json: true, timeout: 30000 });
    if (typeof t === 'string') t = JSON.parse(t);
    const H = { Authorization: 'Bearer ' + t.access_token };
    const nomi = [];
    let pag = null;
    do {
      const url = `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(cfg.play_bucket)}/o?prefix=${encodeURIComponent(`stats/ratings/ratings_${cfg.play_package}_`)}&maxResults=1000${pag ? '&pageToken=' + encodeURIComponent(pag) : ''}`;
      let d = await (async () => { let u; for (let t = 1; t <= 5; t++) { try { return await helpers.httpRequest({ method: 'GET', url, headers: H, json: true, timeout: 30000 }); } catch (e) { u = e; if (['403', '404'].includes(String(e.httpCode ?? ''))) throw e; await new Promise((ok) => setTimeout(ok, 10000 * 2 ** (t - 1))); } } throw u; })();  // elenco dei report: stessi tentativi dei file
      if (typeof d === 'string') d = JSON.parse(d);
      nomi.push(...(d.items ?? []).map((o) => o.name).filter((n) => /_country\.csv$/.test(n)));
      pag = d.nextPageToken ?? null;
    } while (pag);
    // righe per paese e giorno, da tutti i mesi (per l'andamento settimanale nell'Excel)
    const perPaese = new Map(paesi.map((p) => [p.toUpperCase(), new Map()]));
    for (const nome of nomi.sort()) {
      // Cloud Storage a volte non risponde in tempo (timeout su un file): fino a 5 tentativi, attese di 10, 20, 40 e 80 secondi
      let dati = null, ultimo = null;
      for (let t = 1; t <= 5 && dati === null; t++) {
        try {
          dati = await helpers.httpRequest({ method: 'GET', url: `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(cfg.play_bucket)}/o/${encodeURIComponent(nome)}?alt=media`, headers: H, encoding: 'arraybuffer', timeout: 120000 });
        } catch (e) {
          ultimo = e;
          if (String(e.httpCode ?? '') === '403') throw e;
          await new Promise((ok) => setTimeout(ok, 10000 * 2 ** (t - 1)));
        }
      }
      if (dati === null) throw ultimo;
      const buf = Buffer.from(dati);
      const testo = buf[0] === 0xff && buf[1] === 0xfe ? buf.slice(2).toString('utf16le') : buf.toString('utf8').replace(/^﻿/, '');
      const [intest, ...righe] = testo.split(/\r?\n/).filter(Boolean);
      const col = intest.split(',').map((c) => c.trim());
      const iD = col.indexOf('Date'), iC = col.indexOf('Country'), iG = col.indexOf('Daily Average Rating'), iT = col.indexOf('Total Average Rating');
      for (const r of righe) {
        const c = r.split(',');
        const m = perPaese.get(String(c[iC] ?? '').trim());
        if (!m) continue;
        const tot = parseFloat(c[iT]), gio = parseFloat(c[iG]);
        m.set(String(c[iD]).trim(), { totale: Number.isNaN(tot) ? null : tot, del_giorno: Number.isNaN(gio) ? null : gio });
      }
    }
    for (const p of paesi) {
      const m = perPaese.get(p.toUpperCase());
      const date = [...m.keys()].filter((d) => m.get(d).totale !== null).sort();
      if (!date.length) { android.paesi.push({ paese: p, nome: NOMI[p] ?? p, stato: 'nessun dato per questo paese' }); continue; }
      const ultima = date[date.length - 1];
      const prima = date.filter((d) => giorno(ultima) - giorno(d) >= 7).pop() ?? null;
      android.paesi.push({
        paese: p, nome: NOMI[p] ?? p, stato: 'ok', dati_fino_al: ultima, voto: r2(m.get(ultima).totale),
        data_prima: prima, voto_prima: prima ? r2(m.get(prima).totale) : null,
      });
      // serie settimanale: il voto totale di ogni domenica (o dell'ultimo giorno disponibile prima)
      for (let g = giorno(date[0]); g <= giorno(ultima); g++) {
        const d = comeData(g);
        if (new Date(g * 86400000).getUTCDay() !== 0 && d !== ultima) continue;
        const v = date.filter((x) => x <= d).pop();
        if (v) android.serie_settimanale.push({ paese: p, nome: NOMI[p] ?? p, settimana_fino_al: d, dati_del: v, voto: r2(m.get(v).totale) });
      }
    }
    android.report_letti = nomi.length;
  } catch (e) {
    const codice = String(e.httpCode ?? e.cause?.status ?? e.response?.status ?? '');
    android.stato = codice === '403' || /403|forbidden|denied/i.test(e.message) ? 'permesso sui report non attivo' : 'report non letti: ' + e.message;
    // Google non ha risposto nemmeno dopo i tentativi: si mostrano i voti dell'ultimo giro riuscito, dicendo di quando
    // sono (meglio un dato vecchio dichiarato che nessun dato); il giro dopo ci riprova
    const precedente = storico.ultimo_giro?.android;
    if (precedente && Array.isArray(precedente.paesi) && precedente.paesi.some((p) => p.stato === 'ok')) {
      const quando = precedente.dati_del_giro ?? storico.ultimo_giro.oggi;
      android.paesi = precedente.paesi;
      android.dati_del_giro = quando;
      android.stato = `Google non ha risposto in questo giro: voti del giro del ${String(quando).slice(8, 10)}/${String(quando).slice(5, 7)}`;
    }
  }
}
if (android.stato === 'ok') android.dati_del_giro = oggi;

// --- versione pubblicata oggi negli store (richiesta del 17/11: negli avvisi a grappolo dire se la versione con
// il problema e' quella che la gente scarica adesso, non solo «la piu' recente vista nelle recensioni»)
// - iOS: il campo version del servizio pubblico di Apple letto sopra;
// - Android: la traccia di produzione dell'API di Google Play. Per leggerla Google chiede di aprire una bozza
//   («edit») che poi si cancella subito: non si pubblica e non si cambia niente. Il nome della release e'
//   del tipo «375 (3.3.8)»: si prende il numero tra parentesi, che e' quello scritto nelle recensioni.
const versione_pubblicata = { ios: ios.paesi.find((p) => p.versione)?.versione ?? null, android: null, android_stato: 'ok' };
if (!cfg.play_package || !$env.GOOGLE_PLAY_CREDENZIALI_B64) versione_pubblicata.android_stato = 'non configurato';
else {
  try {
    const account = JSON.parse(Buffer.from($env.GOOGLE_PLAY_CREDENZIALI_B64, 'base64').toString('utf8'));
    const b64url = (x) => Buffer.from(typeof x === 'string' ? x : JSON.stringify(x)).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
    const ora = Math.floor(Date.now() / 1000);
    const testa = b64url({ alg: 'RS256', typ: 'JWT' });
    const corpo = b64url({ iss: account.client_email, scope: 'https://www.googleapis.com/auth/androidpublisher', aud: 'https://oauth2.googleapis.com/token', iat: ora, exp: ora + 3600 });
    const firma = crypto.createSign('RSA-SHA256').update(`${testa}.${corpo}`).sign(account.private_key, 'base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
    let t = await helpers.httpRequest({ method: 'POST', url: 'https://oauth2.googleapis.com/token', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: `grant_type=${encodeURIComponent('urn:ietf:params:oauth:grant-type:jwt-bearer')}&assertion=${testa}.${corpo}.${firma}`, json: true, timeout: 30000 });
    if (typeof t === 'string') t = JSON.parse(t);
    const H = { Authorization: 'Bearer ' + t.access_token };
    const base = `https://androidpublisher.googleapis.com/androidpublisher/v3/applications/${encodeURIComponent(cfg.play_package)}/edits`;
    let e = await helpers.httpRequest({ method: 'POST', url: base, headers: H, json: true, timeout: 30000 });
    if (typeof e === 'string') e = JSON.parse(e);
    try {
      let tr = await helpers.httpRequest({ method: 'GET', url: `${base}/${e.id}/tracks/production`, headers: H, json: true, timeout: 30000 });
      if (typeof tr === 'string') tr = JSON.parse(tr);
      // la release completata; durante un rilascio graduale c'e' anche quella «inProgress», che e' la piu' nuova
      const rel = (tr.releases ?? []).find((r) => r.status === 'inProgress') ?? (tr.releases ?? []).find((r) => r.status === 'completed');
      if (rel) {
        versione_pubblicata.android = (String(rel.name ?? '').match(/\(([^)]+)\)/)?.[1] ?? rel.name ?? null);
        if (rel.status === 'inProgress') versione_pubblicata.android_stato = `in rilascio graduale (${Math.round(100 * (rel.userFraction ?? 0))}% degli utenti)`;
      } else versione_pubblicata.android_stato = 'nessuna release in produzione';
    } finally {
      await helpers.httpRequest({ method: 'DELETE', url: `${base}/${e.id}`, headers: H, timeout: 30000 }).catch(() => {});
    }
  } catch (e) {
    versione_pubblicata.android_stato = 'non letta: ' + e.message;
  }
}

const risultato = { generato_il: new Date().toISOString(), oggi, paesi, ios, android, versione_pubblicata, istantanee_ios: storico.istantanee_ios };
return [{
  json: { path: `${cfg.output_dir}/storico_voti.json`, voto_store: risultato },
  // nel file anche il risultato dell'ultimo giro (senza la serie lunga di Android), per poterlo controllare
  binary: { data: { data: Buffer.from(JSON.stringify({ istantanee_ios: storico.istantanee_ios, ultimo_giro: { ...risultato, istantanee_ios: undefined, android: { ...android, serie_settimanale: undefined } } }, null, 1), 'utf8').toString('base64'), mimeType: 'application/json', fileName: 'storico_voti.json' } },
}];

// TELEGRAM: RIASSUNTO, DIGEST E AVVISI
// Alla fine di ogni giro, se TELEGRAM_BOT_TOKEN e TELEGRAM_CHAT_ID sono impostati:
// 1. un messaggio breve con i punti principali (numeri presi dall'aggregazione, scritti dal codice);
// 2. il digest completo come file digest.md (lo manda il nodo Telegram nativo che segue);
// 3. un avviso per ogni recensione NUOVA di questo giro con una segnalazione ad alta priorita'
//    (nuova = id dello store mai visto prima: si sa solo quando il giro scarica dallo store);
// 4. un avviso a grappolo quando almeno GRAPPOLO_MINIMO recensioni recenti riportano lo stesso problema sulla
//    stessa piattaforma e versione (calcolato nell'Aggregazione), se almeno una e' nuova di questo giro.
// I testi sono quelli gia' controllati dal workflow: le prove delle segnalazioni sono frasi
// esatte delle recensioni, con i dati personali gia' oscurati dal guardrail di ingresso.
// Se Telegram non risponde, il giro NON fallisce: l'errore resta scritto nel risultato.
const helpers = this.helpers;
const cfg = $('Configurazione').first().json;
const token = $env.TELEGRAM_BOT_TOKEN, chat = $env.TELEGRAM_CHAT_ID;
if (!token || !chat) return [{ json: { telegram: 'non configurato: mancano TELEGRAM_BOT_TOKEN o TELEGRAM_CHAT_ID' } }];
// i giri di prova (cartella di uscita diversa da quella ufficiale) non mandano niente, salvo TELEGRAM_ANCHE_PROVE=true
if (cfg.output_dir !== '/files/output' && String($env.TELEGRAM_ANCHE_PROVE || '').toLowerCase() !== 'true') return [{ json: { telegram: 'non inviato: giro di prova in ' + cfg.output_dir } }];

const A = $('Aggregazione').first().json.aggregazione;
const fatti = $('Fatti per il digest').first().json.fatti;
let digest = '';
try { digest = $('Usa digest di riserva').first().json.digest; } catch (e) { digest = $('Verifica digest').first().json.digest; }
let unione = null;
try { unione = $('Unisci con l\'archivio').first().json; } catch (e) { unione = null; }
const nuove = new Set(unione?.nuove_id_store ?? []);

const api = (metodo) => `https://api.telegram.org/bot${token}/${metodo}`;
const esiti = [];
async function invia(testo) {
  try {
    const r = await helpers.httpRequest({ method: 'POST', url: api('sendMessage'), body: { chat_id: chat, text: conAccenti(testo).slice(0, 4000), disable_web_page_preview: true }, json: true, timeout: 30000 });
    esiti.push({ tipo: 'messaggio', ok: !!r.ok });
  } catch (e) {
    esiti.push({ tipo: 'messaggio', ok: false, errore: e.message });
  }
}
// accenti veri al posto dell'apostrofo («e'» -> «è», «perche'» -> «perché»), solo FUORI dalle citazioni «...»,
// che restano copiate parola per parola (17/11: nello stesso testo c'erano «e'» del codice e «è» del modello)
const ACUTE = new Set(['perche', 'poiche', 'affinche', 'benche', 'finche', 'giacche', 'nonche', 'sicche', 'ne']);
const GRAVE = { a: 'à', e: 'è', i: 'ì', o: 'ò', u: 'ù', A: 'À', E: 'È', I: 'Ì', O: 'Ò', U: 'Ù' };
const accentaPezzo = (s) => s.replace(/(^|[^A-Za-zÀ-ÿ'])([A-Za-zÀ-ÿ]*?)([aeiouAEIOU])'(?=[\s.,;:!?)\]]|$)/g, (m, prima, radice, v) => {
  const parola = (radice + v).toLowerCase();
  if (parola === 'po') return m;
  return prima + radice + (ACUTE.has(parola) && v.toLowerCase() === 'e' ? (v === 'E' ? 'É' : 'é') : GRAVE[v]);
});
const conAccenti = (testo) => String(testo).split(/(«[^»]*»)/).map((p) => (p.startsWith('«') ? p : accentaPezzo(p))).join('');

// --- 1. riassunto breve
const pct = (x) => `${String(x).replace('.', ',')}%`;
// numeri interi con il punto delle migliaia, uguali in tutto il messaggio (1.234, 12.345)
const mig = (x) => String(Math.round(Number(x))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const S = A.sentiment_complessivo;
// lingue delle recensioni (17/11: entrano anche le recensioni in inglese di Regno Unito e Stati Uniti)
const NOME_LINGUA = { it: 'italiano', en: 'inglese', es: 'spagnolo', fr: 'francese', de: 'tedesco', pt: 'portoghese', ro: 'rumeno' };
const lingueOrd = Object.entries(A.lingue ?? {}).filter(([l]) => l !== 'und').sort((a, b) => b[1] - a[1]);
const totLingue = Object.values(A.lingue ?? {}).reduce((s, x) => s + x, 0);
const lingueGrandi = lingueOrd.filter(([, n]) => n >= 0.02 * totLingue);
const altreLingue = totLingue - lingueGrandi.reduce((s, [, n]) => s + n, 0);
const fraseLingue = lingueGrandi.length <= 1
  ? `in ${NOME_LINGUA[lingueGrandi[0]?.[0]] ?? lingueGrandi[0]?.[0] ?? 'italiano'}`
  : lingueGrandi.map(([l, n]) => `${mig(n)} in ${NOME_LINGUA[l] ?? l}`).join(', ') + (altreLingue > 0 ? `, ${mig(altreLingue)} in altre lingue o non riconosciute` : '');
const righe = [
  `Recensioni dell'app: giro del ${new Date().toLocaleDateString('it-IT', { timeZone: 'Europe/Rome' })}`,
  '',
  // date in formato gg/mm/aaaa come nel resto del messaggio (verifica alla cieca del 17/11)
  `${mig(A.meta.recensioni_aggregate)} recensioni scritte analizzate, ${fraseLingue} (dal ${String(A.meta.prima_data).split('-').reverse().join('/')} al ${String(A.meta.ultima_data).split('-').reverse().join('/')}), voto medio delle recensioni scritte ${String(A.voto_medio).replace('.', ',')} (non e' il voto dello store, che conta anche chi da' solo le stelle). Positive ${pct(S.positive.pct)}, negative ${pct(S.negative.pct)}.`,
];
if (unione) righe.push(`Nuove recensioni scaricate in questo giro: ${unione.nuove} (iOS ${unione.nuove_ios ?? '-'}, Android ${unione.nuove_android ?? '-'}).`);
righe.push('');
for (const x of fatti.frasi_piattaforme ?? []) righe.push(`- ${x}.`);
if (unione && unione.android && unione.android !== 'ok') righe.push(`(Android: ${unione.android})`);
if (unione && unione.ios && unione.ios !== 'ok') righe.push(`(iOS: ${unione.ios})`);
if (unione && unione.android_storico && !String(unione.android_storico).startsWith('ok')) righe.push(`(Storico Android: ${unione.android_storico})`);
// --- voto negli store per mercato (nodo «Voto negli store»): il voto che si vede negli store, con tutte le
//     valutazioni (anche quelle senza testo), confrontato con una settimana prima
let VS = null;
try { VS = $('Voto negli store').first().json.voto_store ?? null; } catch (e) { VS = null; }
if (VS) {
  const v2 = (x) => Number(x).toFixed(2).replace('.', ',');
  // punto delle migliaia sempre (toLocaleString in italiano non lo mette sui numeri di 4 cifre: «1234» accanto a «12.345»)
  const intero = (x) => String(Math.round(Number(x))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const gm2 = (d) => `${String(d).slice(8, 10)}/${String(d).slice(5, 7)}`;
  righe.push('', 'Voto negli store per mercato (tutte le valutazioni, anche quelle senza testo, di ogni lingua):');
  if (VS.ios.stato !== 'ok') righe.push(`- iOS: ${VS.ios.stato}`);
  for (const p of VS.ios.paesi) {
    if (p.stato !== 'ok') { righe.push(`- iOS ${p.nome}: ${p.stato}`); continue; }
    let t = `- iOS ${p.nome}: ${v2(p.voto)} su ${intero(p.valutazioni)} valutazioni`;
    if (p.data_prima) {
      t += ` (il ${gm2(p.data_prima)}: ${v2(p.voto_prima)}`;
      if (p.media_voti_nuovi !== undefined && p.media_voti_nuovi !== null) t += `; da allora ${intero(p.voti_nuovi)} voti nuovi, media ${v2(p.media_voti_nuovi)}`;
      else if (p.media_voti_nuovi_nota) t += `; voti nuovi: ${p.media_voti_nuovi_nota}`;
      t += ')';
    } else t += ' (primo rilevamento: il confronto dalla prossima settimana)';
    righe.push(t);
  }
  if (VS.android.stato !== 'ok') righe.push(`- Android: ${VS.android.stato}`);
  for (const p of VS.android.paesi) {
    if (p.stato !== 'ok') { righe.push(`- Android ${p.nome}: ${p.stato}`); continue; }
    righe.push(`- Android ${p.nome}: ${v2(p.voto)} (dati di Google fino al ${gm2(p.dati_fino_al)}${p.data_prima ? `; il ${gm2(p.data_prima)}: ${v2(p.voto_prima)}` : ''})`);
  }
}
// --- ultima versione dell'app per piattaforma: contro la versione prima, e quale versione c'e' ora nello store
//     (richiesta del 17/11: il peggioramento di una versione deve essere scritto in chiaro nel messaggio)
{
  const NOMI_PF = { ios: 'iOS', android: 'Android' };
  const VP = VS?.versione_pubblicata ?? null;
  const righeV = [];
  for (const p of A.per_piattaforma ?? []) {
    const nv = p.negative_ultima_versione;
    if (!nv) continue;
    const inStore = VP?.[p.piattaforma] ?? null;
    const store = inStore ? (inStore === nv.ultima_versione ? ' (è quella pubblicata ora nello store)' : `; nello store ora c'è la ${inStore}`) : '';
    // una riga per lingua: italiano e inglese separati (la quota di inglese puo' cambiare da una versione all'altra)
    let t = `- ${NOMI_PF[p.piattaforma] ?? p.piattaforma} ${nv.ultima_versione}${store}, contro la ${nv.versione_prima}:`;
    for (const x of nv.per_lingua ?? []) {
      if (!x.recensioni_ultima) continue;
      t += `\n  in ${NOME_LINGUA[x.lingua] ?? x.lingua}: ${pct(x.pct_negative_ultima)} negative o miste su ${mig(x.recensioni_ultima)} recensioni, contro ${x.recensioni_prima ? pct(x.pct_negative_prima) + ' su ' + mig(x.recensioni_prima) : 'nessuna recensione'}: `;
      t += x.esito === 'pochi dati' ? 'pochi dati per un verdetto.' : x.esito === 'oltre il rumore' ? (x.differenza_punti > 0 ? 'PEGGIORATA, oltre il rumore statistico.' : 'migliorata, oltre il rumore statistico.') : 'differenza entro il rumore statistico.';
    }
    const peggio = (p.andamento_ultima_versione ?? []).filter((x) => x.significativo && ((x.misura === 'pct_recensioni_che_lo_criticano' && x.differenza_punti > 0) || (x.misura === 'pct_recensioni_che_lo_apprezzano' && x.differenza_punti < 0)));
    for (const x of peggio) t += `\n  ${x.nome} (in ${NOME_LINGUA[x.lingua] ?? x.lingua}): ${x.misura === 'pct_recensioni_che_lo_criticano' ? 'criticato' : 'apprezzato'} nel ${pct(x.valore_nuovo)} delle recensioni contro il ${pct(x.valore_confronto)} della ${nv.versione_prima} (oltre il rumore).`;
    righeV.push(t);
  }
  if (VP && /^in rilascio/.test(VP.android_stato ?? '')) righeV.push(`(Android ${VP.android}: ${VP.android_stato})`);
  else if (VP && VP.android_stato && VP.android_stato !== 'ok') righeV.push(`(Versione Android nello store: ${VP.android_stato})`);
  if (righeV.length) righe.push('', "Ultima versione dell'app con abbastanza recensioni, contro la versione prima:", ...righeV);
}
righe.push('', 'Piu\' criticati:');
for (const x of A.classifiche.piu_criticati.slice(0, 3)) righe.push(`- ${x.nome}: ${mig(x.recensioni_negative)} recensioni (${pct(x.pct_recensioni_che_lo_criticano)} del totale)`);
// andamento per piattaforma: ultime due settimane complete e ultimo mese completo, contro il periodo prima
// (numeri e verdetti dall'Aggregazione: «oltre il rumore», «entro il rumore» o «pochi dati»)
const PC = A.periodi_di_calendario;
if (PC) {
  const NOMI = { ios: 'iOS', android: 'Android' };
  const MESI = ['gennaio', 'febbraio', 'marzo', 'aprile', 'maggio', 'giugno', 'luglio', 'agosto', 'settembre', 'ottobre', 'novembre', 'dicembre'];
  const gm = (d) => `${d.slice(8, 10)}/${d.slice(5, 7)}`;
  const nomePeriodo = (p, tipo) => (tipo === 'mesi' ? `${MESI[Number(p.slice(5, 7)) - 1]} ${p.slice(0, 4)}` : `dal ${gm(p.slice(0, 10))} al ${gm(p.slice(-10))}`);
  // il periodo e' scritto su ogni riga: iOS e Android possono avere ultimi periodi completi diversi
  // (correzione dopo la verifica alla cieca del 16/11: «pochi dati» anche quando manca il periodo prima,
  // e «dati solo dal» quando il periodo e' il primo dell'archivio e parte a meta')
  for (const [tipo, titolo] of [['due_settimane', 'Ultime due settimane complete'], ['mesi', 'Ultimo mese completo']]) {
    const righeP = [];
    for (const s of PC[tipo].filter((x) => x.piattaforma !== 'tutte')) {
      const p = [...s.periodi].reverse().find((x) => !x.in_corso);
      if (!p) continue;
      const testa = `- ${NOMI[s.piattaforma] ?? s.piattaforma}${s.lingua ? ' in ' + (NOME_LINGUA[s.lingua] ?? s.lingua) : ''}, ${nomePeriodo(p.periodo, tipo)}${p.dati_solo_dal ? ` (dati solo dal ${gm(p.dati_solo_dal)})` : ''}`;
      if (!p.recensioni) { righeP.push(`${testa}: nessuna recensione`); continue; }
      const c = p.confronto;
      let t = `${testa}: ${p.recensioni} recensioni, ${pct(p.pct_negative)} negative`;
      if (c && c.pct_negative_prima !== null) t += ` (prima ${pct(c.pct_negative_prima)}): ${c.esito}`;
      else t += ` (nessun dato sul periodo prima${p.recensioni < 20 ? '; pochi dati' : ''})`;
      righeP.push(t);
    }
    if (righeP.length) righe.push('', `${titolo}:`, ...righeP);
  }
}
const sig = A.andamento.filter((x) => x.significativo);
righe.push('', sig.length ? `Temi: ${sig.length} cambiamenti oltre la soglia statistica tra l'ultimo periodo e i precedenti (dettagli nel digest).` : 'Temi: nessun cambiamento oltre la soglia statistica tra l\'ultimo periodo e i precedenti.');
// recensioni da guardare: prima quelle RECENTI (su cui si puo' fare qualcosa), poi il totale dell'archivio
// (il totale di anni di archivio e' troppo per chi legge ogni settimana)
const giornoN = (d) => Math.round(Date.parse(String(d).slice(0, 10) + 'T00:00:00Z') / 86400000);
const oggiN = giornoN(cfg.grappolo_oggi ?? new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Rome' }));
const daGuardareRecenti = $('Valida e completa').all().map((i) => i.json)
  .filter((r) => r.needs_attention && r.stato !== 'duplicato' && r.published_date && oggiN - giornoN(r.published_date) < cfg.avvisi_giorni);
righe.push(`Da guardare negli ultimi ${cfg.avvisi_giorni} giorni: ${daGuardareRecenti.length} recensioni, ${daGuardareRecenti.filter((r) => (r.segnalazioni ?? []).length).length} con un problema preciso, di cui ${daGuardareRecenti.filter((r) => r.priorita === 'alta').length} con priorita' alta (foglio Segnalazioni dell'Excel).`);
const S2 = A.segnalazioni;
const precise = S2.con_un_problema_preciso ?? null;
righe.push(precise === null
  ? `In tutto l'archivio: ${S2.totale} segnalate, di cui ${S2.per_priorita.alta} con priorita' alta.`
  : `In tutto l'archivio (dal ${String(A.meta.prima_data).slice(0, 4)}): ${mig(S2.totale)} da guardare, ${mig(precise)} con un problema preciso, di cui ${mig(S2.per_priorita.alta)} con priorita' alta; le altre ${mig(S2.totale - precise)} solo per voto basso o per voto e testo in contrasto.`);
if (fatti.frase_campagne) righe.push('', fatti.frase_campagne);
// avvisi a grappolo (vedi Aggregazione): solo quelli con almeno una recensione nuova di questo giro,
// cosi' lo stesso grappolo non viene ripetuto a ogni giro se non arriva niente di nuovo
const G = A.avviso_a_grappolo ?? { grappoli: [] };
const grappoliDaAvvisare = G.grappoli.filter((g) => g.recensioni.some((x) => nuove.has(x.chiave_store)));
if (grappoliDaAvvisare.length) righe.push('', `Avvisi a grappolo: ${grappoliDaAvvisare.length} (stesso problema sulla stessa versione, in ${cfg.grappolo_giorni} giorni). Li trovi qui sotto.`);
// grappoli ancora aperti ma senza recensioni nuove: una riga sola, senza ripetere l'avviso (verifica alla cieca 17/11:
// il messaggio taceva un grappolo vero solo perche' le sue recensioni erano gia' state viste)
const grappoliAperti = G.grappoli.filter((g) => !grappoliDaAvvisare.includes(g));
if (grappoliAperti.length) {
  const NPF = { ios: 'iOS', android: 'Android' };
  righe.push('', `Grappoli ancora aperti negli ultimi ${cfg.grappolo_giorni} giorni, senza recensioni nuove: ${grappoliAperti.map((g) => `${NPF[g.piattaforma] ?? g.piattaforma}${g.versione ? ' ' + g.versione : ''}, ${g.nome_categoria} (${g.quante})`).join('; ')}. Dettagli nel foglio Grappoli dell'Excel.`);
}
righe.push('', 'Il digest completo e\' nel file qui sotto.');
await invia(righe.join('\n'));

// --- 2. il digest completo lo manda come file il nodo Telegram nativo (qui sotto): dal nodo Code i file
//        arrivano rovinati (prova del 14/11: "there is no document in the request")

// --- 3. avvisi per le recensioni nuove con priorita' alta
const recensioni = new Map($('Recensioni pronte').all().map((i) => [i.json.review_id, i.json]));
const analisi = $('Valida e completa').all().map((i) => i.json);
// solo recensioni RECENTI (pubblicate negli ultimi AVVISI_GIORNI giorni): quando entra uno storico (per esempio
// i report Android di anni) migliaia di recensioni sono «nuove» per l'archivio ma vecchie per chi legge,
// e non devono diventare avvisi urgenti. Restano nell'archivio, nelle analisi, nel digest e nell'Excel.
const giornoDi = (d) => Math.round(Date.parse(String(d).slice(0, 10) + 'T00:00:00Z') / 86400000);
const oggiAvvisi = giornoDi(cfg.grappolo_oggi ?? new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Rome' }));
const recente = (x) => x.published_date && oggiAvvisi - giornoDi(x.published_date) < cfg.avvisi_giorni;
const nuoveAlta = analisi.filter((r) => {
  const x = recensioni.get(r.review_id);
  return x && nuove.has(`${x.piattaforma}|${x.id_store}`) && (r.segnalazioni ?? []).some((s) => s.priorita === 'alta');
});
const urgenti = nuoveAlta.filter((r) => recente(recensioni.get(r.review_id)));
const MAX_AVVISI = 15;
for (const r of urgenti.slice(0, MAX_AVVISI)) {
  const x = recensioni.get(r.review_id);
  const s = r.segnalazioni.find((y) => y.priorita === 'alta');
  await invia([
    `Avviso: ${s.nome_categoria} (priorita' alta)`,
    `Recensione ${r.review_id}, ${x.published_date ?? ''}, voto ${x.rating ?? '-'}, ${x.piattaforma}${x.versione ? ' ' + x.versione : ''}`,
    // le recensioni sono affermazioni dell'utente, non fatti accertati: si dice sempre chi lo afferma
    /^(l'utente|secondo l'utente)/i.test(s.sintesi) ? s.sintesi : `Secondo l'utente: ${s.sintesi}`,
    `Dalla recensione: «${s.evidenza}»`,
  ].join('\n'));
}
if (urgenti.length > MAX_AVVISI) await invia(`Altre ${urgenti.length - MAX_AVVISI} recensioni nuove con priorita' alta: sono nel digest e in recensioni_diagnostica.jsonl.`);
if (nuoveAlta.length > urgenti.length) await invia(`Nell'archivio sono entrate anche ${nuoveAlta.length - urgenti.length} recensioni con priorita' alta piu' vecchie di ${cfg.avvisi_giorni} giorni (storico): niente avvisi singoli, sono nel digest e nel foglio Segnalazioni dell'Excel.`);

// --- 4. avvisi a grappolo: stesso problema, stessa piattaforma e stessa versione, in pochi giorni
//        (per esempio tre persone che sulla stessa versione scrivono «ho pagato ma non ho ricevuto l'acquisto»)
const NOME_PF = { ios: 'iOS', android: 'Android' };
const dataIt = (d) => (d ? String(d).slice(0, 10).split('-').reverse().join('/') : '');
const MAX_GRAPPOLI = 10, MAX_FRASI = 5;
for (const g of grappoliDaAvvisare.slice(0, MAX_GRAPPOLI)) {
  const pf = NOME_PF[g.piattaforma] ?? g.piattaforma;
  const nuoveQui = g.recensioni.filter((x) => nuove.has(x.chiave_store)).length;
  const inStore = VS?.versione_pubblicata?.[g.piattaforma] ?? null;
  const frase = !g.versione
    ? 'Lo store non indica la versione.'
    : inStore
      ? (inStore === g.versione ? `È la versione pubblicata ora nello store ${pf}: la scaricano i nuovi utenti.` : `Nello store ${pf} ora c'è la versione ${inStore}: chi ha questo problema ha una versione diversa.`)
      : (g.e_la_versione_piu_recente
        ? `È la versione più recente tra quelle viste nelle recensioni ${pf} (la versione dello store non è stata letta).`
        : `È una versione vecchia: la più recente vista nelle recensioni ${pf} è la ${g.versione_piu_recente_vista}.`);
  const testo = [
    `Avviso a grappolo: ${g.nome_categoria}`,
    `${g.quante} recensioni ${pf}${g.versione ? ' sulla versione ' + g.versione : ''} dal ${dataIt(g.dal)} al ${dataIt(g.al)}, ${nuoveQui} nuove in questo giro.`,
    frase,
    'Dalle recensioni (sono affermazioni degli utenti):',
    ...g.recensioni.slice(0, MAX_FRASI).map((x) => `- «${x.evidenza}» (voto ${x.voto ?? '-'}, ${dataIt(x.data)})`),
  ];
  if (g.quante > MAX_FRASI) testo.push(`... e altre ${g.quante - MAX_FRASI}: sono in aggregazione.json.`);
  testo.push('Da confrontare con i ticket del servizio clienti.');
  await invia(testo.join('\n'));
}
if (grappoliDaAvvisare.length > MAX_GRAPPOLI) await invia(`Altri ${grappoliDaAvvisare.length - MAX_GRAPPOLI} avvisi a grappolo: sono in aggregazione.json.`);

// esito scritto accanto agli altri risultati (telegram.json), per controllare che cosa e' partito
const esito = {
  inviato_il: new Date().toISOString(),
  avvisi_urgenti: urgenti.length,
  avvisi_a_grappolo: grappoliDaAvvisare.map((g) => ({ categoria: g.categoria, piattaforma: g.piattaforma, versione: g.versione, quante: g.quante })),
  nuove_recensioni: unione?.nuove ?? null,
  esiti,
};
const b64 = (t) => Buffer.from(t, 'utf8').toString('base64');
return [{
  json: { telegram: 'testi inviati', path: `${cfg.output_dir}/telegram.json`, chat_id: String(chat), ...esito },
  binary: {
    data: { data: b64(digest), mimeType: 'text/markdown', fileName: 'digest.md' },
    esito: { data: b64(JSON.stringify(esito, null, 2)), mimeType: 'application/json', fileName: 'telegram.json' },
  },
}];

// DIGEST COME TESTO (riserva)
// Si arriva qui solo se il nodo Telegram non e' riuscito a mandare il file digest.md.
// Il digest arriva comunque, spezzato ai paragrafi (limite di Telegram: 4096 caratteri per messaggio).
const helpers = this.helpers;
const token = $env.TELEGRAM_BOT_TOKEN, chat = $env.TELEGRAM_CHAT_ID;
let digest = '';
try { digest = $('Usa digest di riserva').first().json.digest; } catch (e) { digest = $('Verifica digest').first().json.digest; }
const SEP = String.fromCharCode(10, 10);
const pezzi = [];
let corrente = '';
for (const par of digest.split(SEP)) {
  if ((corrente + SEP + par).length > 3800 && corrente) { pezzi.push(corrente); corrente = par; } else corrente = corrente ? corrente + SEP + par : par;
}
if (corrente) pezzi.push(corrente);
let inviati = 0;
for (const [i, t] of pezzi.entries()) {
  const r = await helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${token}/sendMessage`, body: { chat_id: chat, text: `Digest (${i + 1}/${pezzi.length})` + SEP + t, disable_web_page_preview: true }, json: true, timeout: 30000 });
  if (r.ok) inviati++;
}
return [{ json: { digest_come_testo: true, messaggi: pezzi.length, inviati } }];

// PREPARA IL FILE EXCEL (recensioni_app.xlsx)
// Tabelle da aprire in Excel (o Tableau) per chi gestisce l'app, con i confronti tra periodi (mese per mese e ogni due settimane). Un solo file con piu' fogli, scritto accanto agli
// altri risultati e mandato su Telegram dopo il digest.
// Nessun numero nuovo: tutto viene dall'Aggregazione (periodi, confronti, grappoli) o e' un semplice conteggio
// delle analisi delle recensioni. Il file .xlsx e' costruito a mano (zip senza compressione + XML), perche' nel
// nodo Code non ci sono librerie esterne.
const cfg = $('Configurazione').first().json;
const A = $('Aggregazione').first().json.aggregazione;
const tax = $('Valida tassonomia').first().json;
const analisi = $('Valida e completa').all().map((i) => i.json);
const pronte = new Map($('Recensioni pronte').all().map((i) => [i.json.review_id, i.json]));

const nomeAspetto = Object.fromEntries([...(A.aspetti ?? []).map((a) => [a.aspect, a.nome]), ...tax.aspetti.map((a) => [a.aspect, a.nome])]);
const SENT = { positive: 'positivo', negative: 'negativo', mixed: 'misto', neutral: 'neutro' };
const PF = { ios: 'iOS', android: 'Android', tutte: 'tutte' };
const MISURA = { pct_recensioni_che_lo_criticano: '% recensioni che lo criticano', pct_recensioni_che_lo_apprezzano: '% recensioni che lo apprezzano' };
const pct = (a, b) => (b ? Math.round((1000 * a) / b) / 10 : null);
const media = (xs) => (xs.length ? Math.round((100 * xs.reduce((s, x) => s + x, 0)) / xs.length) / 100 : null);
const siNo = (x) => (x === true ? 'sì' : x === false ? 'no' : '');
const valide = analisi.filter((r) => (r.stato === 'ok' || r.stato === 'ritentata') && !r.sospetta);

// --- fogli: ognuno e' { nome, colonne, righe (array di array) }
const fogli = [];

const R = A.periodi_di_calendario;
fogli.push({
  nome: 'Leggimi',
  colonne: ['foglio', 'che cosa contiene'],
  righe: [
    ['Due settimane', 'Per ogni periodo di due settimane (da lunedì a domenica): recensioni, voto medio, sentiment e confronto con le due settimane prima.'],
    ['Mesi', 'Lo stesso, mese per mese.'],
    ['Confronti', 'Temi: ultimo periodo contro i precedenti e ultima versione dell\'app contro la versione prima (solo con abbastanza recensioni).'],
    ['Temi per mese', 'Per ogni mese e tema: quante recensioni lo apprezzano e quante lo criticano.'],
    ['Versioni', 'Recensioni per versione dell\'app, con la quota di negative.'],
    ['Lingue', 'Recensioni per lingua, con la quota di negative.'],
    ['Segnalazioni', 'Le recensioni da guardare: categoria, priorità, che cosa dice l\'utente e la sua frase.'],
    ['Grappoli', 'Avvisi a grappolo: stesso problema, stessa piattaforma e versione, in pochi giorni.'],
    ['Voto negli store', 'Il voto che si vede negli store (tutte le valutazioni, anche senza testo) per mercato. iOS: una rilevazione a ogni giro (Apple dà solo il voto di oggi), con i voti nuovi tra una rilevazione e la precedente e la loro media. Android: il voto di ogni settimana dai report di Google (dal 2019; Google non dà il numero delle valutazioni).'],
    ['Recensioni', 'Una riga per recensione: dati, sentiment, temi, segnalazioni, testo.'],
    ['', ''],
    ['Come leggere i confronti', '«oltre il rumore» = la differenza è troppo grande per essere un caso (test su due proporzioni con correzione per i confronti multipli). «entro il rumore» = può essere un caso. «pochi dati» = uno dei due periodi ha meno di 20 recensioni: si vedono i numeri ma non si dà un verdetto.'],
    ['p-value e verdetto', 'Un p-value sotto 0,05 può restare «entro il rumore»: con tanti confronti nella stessa tabella qualcuno risulta basso per caso, e la correzione alza la soglia (Benjamini-Hochberg, al massimo 10% di falsi allarmi attesi). Conta la colonna «confronto».'],
    ['Periodo in corso', 'Il mese e le due settimane in corso non sono finiti: i loro numeri cresceranno. La colonna «nota» lo dice, e dice anche quando il primo periodo è incompleto perché i dati partono a metà.'],
    ['iOS e Android', 'Sempre separati: le due piattaforme hanno versioni e storici diversi. Solo il foglio Confronti (periodi) le considera insieme, come il digest.'],
    ['Italiano e inglese', 'Sempre separati nei confronti nel tempo (dal 17/11): la quota di recensioni in inglese è cresciuta molto e l\'inglese è meno negativo, quindi un confronto con le lingue insieme scambierebbe il cambio di composizione per un miglioramento.'],
    ['Attenzione', 'Le recensioni sono affermazioni degli utenti, non fatti accertati.'],
    ['Regola dei periodi', R?.regola ?? ''],
    ['Regola dei grappoli', A.avviso_a_grappolo?.regola ?? ''],
    ['Giro del', new Date().toLocaleString('it-IT', { timeZone: 'Europe/Rome' })],
  ],
});

const LINGUA_X = { it: 'italiano', en: 'inglese' };
const NOMI_LINGUA_X = { it: 'italiano', en: 'inglese', es: 'spagnolo', fr: 'francese', de: 'tedesco', pt: 'portoghese', ro: 'rumeno', und: 'non riconosciuta', altre: 'altre lingue' };
const righePeriodi = (serie) => serie.flatMap((s) => s.periodi.map((p) => [
  PF[s.piattaforma] ?? s.piattaforma, LINGUA_X[s.lingua] ?? s.lingua ?? '', p.periodo, p.in_corso ? 'in corso: incompleto' : p.dati_solo_dal ? `incompleto: dati solo dal ${p.dati_solo_dal}` : '', p.recensioni, p.voto_medio, p.positive, p.negative, p.miste, p.neutre,
  p.pct_negative, p.confronto?.pct_negative_prima ?? null, p.confronto?.differenza_punti ?? null, p.confronto?.esito ?? '', p.confronto?.p_value ?? null,
]));
const colPeriodi = ['piattaforma', 'lingua', 'periodo', 'nota', 'recensioni', 'voto medio', 'positive', 'negative', 'miste', 'neutre', '% negative', '% negative periodo prima', 'differenza (punti)', 'confronto', 'p-value'];
fogli.push({ nome: 'Due settimane', colonne: colPeriodi, righe: righePeriodi(R?.due_settimane ?? []) });
fogli.push({ nome: 'Mesi', colonne: colPeriodi, righe: righePeriodi(R?.mesi ?? []) });

// voto negli store per mercato (nodo «Voto negli store»)
let VS = null;
try { VS = $('Voto negli store').first().json.voto_store ?? null; } catch (e) { VS = null; }
const NOMI_PAESI = { it: 'Italia', gb: 'Regno Unito', us: 'Stati Uniti', es: 'Spagna', fr: 'Francia', de: 'Germania', ch: 'Svizzera' };
const righeVoto = [];
if (VS) {
  const ist = [...(VS.istantanee_ios ?? [])].sort((a, b) => a.paese.localeCompare(b.paese) || a.data.localeCompare(b.data));
  ist.forEach((x, i) => {
    const prima = i > 0 && ist[i - 1].paese === x.paese ? ist[i - 1] : null;
    const nuove = prima && x.valutazioni !== null && prima.valutazioni !== null ? x.valutazioni - prima.valutazioni : null;
    const media = nuove > 0 ? (x.voto * x.valutazioni - prima.voto * prima.valutazioni) / nuove : null;
    const mediaOk = media !== null && media >= 0.95 && media <= 5.05;
    righeVoto.push(['iOS', NOMI_PAESI[x.paese] ?? x.paese, x.data, Math.round(100 * x.voto) / 100, x.valutazioni, nuove,
      mediaOk ? Math.round(100 * Math.min(5, Math.max(1, media))) / 100 : null,
      !prima ? 'prima rilevazione' : nuove !== null && nuove <= 0 ? 'nessun voto nuovo (o valutazioni azzerate)' : media !== null && !mediaOk ? 'media non calcolabile: dati di Apple non coerenti' : '']);
  });
  for (const x of VS.android?.serie_settimanale ?? []) righeVoto.push(['Android', x.nome, x.settimana_fino_al, x.voto, null, null, null, x.dati_del !== x.settimana_fino_al ? `ultimo dato disponibile: ${x.dati_del}` : '']);
}
fogli.push({ nome: 'Voto negli store', colonne: ['piattaforma', 'mercato', 'data', 'voto', 'valutazioni', 'voti nuovi dalla rilevazione prima', 'media dei voti nuovi', 'nota'], righe: righeVoto });

const confronti = [
  ...(A.andamento ?? []).map((x) => [`iOS e Android insieme, ${LINGUA_X[x.lingua] ?? x.lingua ?? ''}`, 'periodo', `${x.ultimo_periodo} contro ${x.periodo_di_confronto}`, x.nome, MISURA[x.misura] ?? x.misura, x.valore_ultimo_periodo, x.valore_periodo_di_confronto, x.differenza_punti, x.p_value, x.significativo ? 'oltre il rumore' : 'entro il rumore']),
  ...(A.per_piattaforma ?? []).flatMap((p) => (p.andamento_ultima_versione ?? []).map((x) => [`${PF[p.piattaforma] ?? p.piattaforma}, ${LINGUA_X[x.lingua] ?? x.lingua ?? ''}`, 'versione', `${x.ultima_versione} contro ${x.confrontata_con}`, x.nome, MISURA[x.misura] ?? x.misura, x.valore_nuovo, x.valore_confronto, x.differenza_punti, x.p_value, x.significativo ? 'oltre il rumore' : 'entro il rumore'])),
];
fogli.push({ nome: 'Confronti', colonne: ['piattaforma', 'tipo', 'confronto', 'tema', 'misura', 'valore nuovo', 'valore di confronto', 'differenza (punti)', 'p-value', 'esito'], righe: confronti });

// temi per mese (conteggi semplici sulle recensioni nei conteggi)
const temiMese = new Map();
const recMese = new Map();
for (const r of valide) {
  if (!r.published_date) continue;
  const m = String(r.published_date).slice(0, 7);
  // anche per lingua (17/11): la quota di inglese cambia nel tempo e mescolarle falsa l'andamento
  const lg = r.language === 'it' || r.language === 'en' ? r.language : 'altre';
  for (const pf of [r.piattaforma ?? 'non indicata']) {
    recMese.set(`${pf}|${lg}|${m}`, (recMese.get(`${pf}|${lg}|${m}`) ?? 0) + 1);
    for (const a of r.aspects ?? []) {
      const k = `${pf}|${lg}|${m}|${a.aspect}`;
      const x = temiMese.get(k) ?? { pf, lg, m, aspect: a.aspect, pos: 0, neg: 0 };
      if (a.sentiment === 'positive') x.pos++;
